  async function openCourierConfigModal80({ cid }) {
    const modal = ensureCourierConfigModal();
    let detach = () => {};
    detach = bindModalClose(modal, () => detach());

    const listEl = modal.querySelector("#courierList");
    const statusEl = modal.querySelector("#courierConfigStatus");
    const newCourierInput = modal.querySelector("#newCourierName");
    const btnAdd = modal.querySelector("#btnAddCourier");
    const defaultBox = modal.querySelector("#defaultCouriers");
    const overdueInput = modal.querySelector("#parcelOverdueDays");
    const btnAudit = modal.querySelector("#btnParcelAudit80");
    if (btnAudit) btnAudit.onclick = () => openParcelAuditModal80({ cid });

    const maintainCommunityName = (state.communities.find((c) => c.id === cid) || {}).name || "";
    const maintainStatus = modal.querySelector("#parcelMaintainStatus80");
    const setMaintainStatus = (msg, isError) => {
      if (!maintainStatus) return;
      maintainStatus.textContent = msg || "";
      maintainStatus.hidden = !msg;
      maintainStatus.classList.toggle("error", !!isError);
    };
    const btnExportParcels = modal.querySelector("#btnExportParcels80");
    if (btnExportParcels) btnExportParcels.onclick = () => {
      setMaintainStatus("匯出中...", false);
      exportParcelsExcel80(cid, maintainCommunityName).finally(() => setMaintainStatus("", false));
    };
    const btnExportParcelAudit = modal.querySelector("#btnExportParcelAudit80");
    if (btnExportParcelAudit) btnExportParcelAudit.onclick = () => {
      setMaintainStatus("匯出中...", false);
      exportParcelAuditExcel80(cid, maintainCommunityName).finally(() => setMaintainStatus("", false));
    };
    const btnBackupParcel = modal.querySelector("#btnBackupParcel80");
    if (btnBackupParcel) btnBackupParcel.onclick = () => {
      setMaintainStatus("備份中...", false);
      backupParcelData80(cid, maintainCommunityName).finally(() => setMaintainStatus("", false));
    };
    const btnPurgeParcels = modal.querySelector("#btnPurgeParcels80");
    if (btnPurgeParcels) btnPurgeParcels.onclick = () => openParcelPurgeModal80({ cid, communityName: maintainCommunityName });

    /* 常用儲位維護 */
    const shelvesEl = modal.querySelector("#parcelShelves80");
    const btnSaveShelves = modal.querySelector("#btnSaveShelves80");
    if (btnSaveShelves) {
      btnSaveShelves.onclick = async () => {
        const shelves = String(shelvesEl ? shelvesEl.value : "")
          .split("\n").map((s) => s.trim()).filter(Boolean);
        setStatus("儲存中...", false);
        try {
          await db.collection("communities").doc(cid).collection("settings").doc("parcel_config")
            .set({ shelves, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
          _parcelConfigCache80 = Object.assign({}, _parcelConfigCache80, { shelves });
          _parcelConfigLoadedCid = String(cid || "").trim();
          setStatus("", false);
          toast(`已儲存 ${shelves.length} 個儲位`);
        } catch (err) {
          setStatus("儲存失敗：" + (err && err.message ? err.message : "未知錯誤"), true);
        }
      };
    }

    /* 通知範本維護 */
    const tplPickupPlace = modal.querySelector("#tplPickupPlace80");
    const tplServiceHours = modal.querySelector("#tplServiceHours80");
    const tplContactPhone = modal.querySelector("#tplContactPhone80");
    const tplFooter = modal.querySelector("#tplFooter80");
    const tplPreview = modal.querySelector("#tplPreview80");
    const readTplInputs = () => ({
      pickupPlace: String(tplPickupPlace ? tplPickupPlace.value : "").trim(),
      serviceHours: String(tplServiceHours ? tplServiceHours.value : "").trim(),
      contactPhone: String(tplContactPhone ? tplContactPhone.value : "").trim(),
      footer: String(tplFooter ? tplFooter.value : "").trim()
    });
    const btnSaveTpl = modal.querySelector("#btnSaveTpl80");
    if (btnSaveTpl) {
      btnSaveTpl.onclick = async () => {
        const notifyTemplate = readTplInputs();
        setStatus("儲存中...", false);
        try {
          await db.collection("communities").doc(cid).collection("settings").doc("parcel_config")
            .set({ notifyTemplate, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
          _parcelConfigCache80 = Object.assign({}, _parcelConfigCache80, { notifyTemplate });
          _parcelConfigLoadedCid = String(cid || "").trim();
          setStatus("", false);
          toast("已儲存通知範本");
        } catch (err) {
          setStatus("儲存失敗：" + (err && err.message ? err.message : "未知錯誤"), true);
        }
      };
    }
    const btnPreviewTpl = modal.querySelector("#btnPreviewTpl80");
    if (btnPreviewTpl) {
      btnPreviewTpl.onclick = () => {
        if (!tplPreview) return;
        const saved = _parcelConfigCache80.notifyTemplate || {};
        _parcelConfigCache80 = Object.assign({}, _parcelConfigCache80, { notifyTemplate: readTplInputs() });
        const text = buildParcelNotifyText80({
          communityName: maintainCommunityName,
          unit: "A-1-1", recipient: "王小明", company: "黑貓宅急便",
          trackNo: "1234567890", serial: "A-20260101-001", shelf: "A櫃-1",
          arrival: "2026/01/01 09:00"
        });
        _parcelConfigCache80 = Object.assign({}, _parcelConfigCache80, { notifyTemplate: saved });
        tplPreview.hidden = false;
        tplPreview.textContent = text;
      };
    }

    const defaultList = [
      "黑貓宅急便", "新竹物流", "宅配通", "嘉里大榮", "中華郵政", 
      "順豐速運", "FedEx", "DHL", "UPS",
      "全家便利商店", "統一超商 (7-11)", "萊爾富", "OK超商", "蝦皮店到店",
      "圓通速遞", "中通快遞", "申通快遞", "韻達快遞"
    ];

    const setStatus = (msg, isError) => {
      statusEl.textContent = msg;
      statusEl.hidden = !msg;
      statusEl.classList.toggle("error", isError);
    };

    const renderDefaultCouriers = (currentCouriers) => {
      const remaining = defaultList.filter(d => !currentCouriers.includes(d));
      defaultBox.innerHTML = remaining.map(name => 
        `<button class="tag" style="cursor:pointer; border-style: dashed;" data-add-default="${name}">+ ${name}</button>`
      ).join("");
      
      defaultBox.querySelectorAll("[data-add-default]").forEach(btn => {
        btn.onclick = () => {
          const name = btn.getAttribute("data-add-default");
          saveCourier(name, true);
        };
      });
    };

    const saveCourier = async (name, isAdd) => {
      if (!name) return;
      setStatus("儲存中...", false);
      try {
        const docRef = db.collection("communities").doc(cid).collection("settings").doc("parcel_config");
        const doc = await docRef.get();
        let couriers = doc.exists ? (doc.data().couriers || []) : [];
        
        if (isAdd) {
          if (!couriers.includes(name)) couriers.push(name);
        } else {
          couriers = couriers.filter(c => c !== name);
        }
        
        await docRef.set({ couriers, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
        newCourierInput.value = "";
        setStatus("", false);
        toast(isAdd ? "已新增" : "已刪除");
      } catch (err) {
        setStatus("操作失敗：" + err.message, true);
      }
    };

    btnAdd.onclick = () => {
      const name = newCourierInput.value.trim();
      if (!name) return toast("請輸入名稱");
      saveCourier(name, true);
    };

    const saveOverdueDays = async () => {
      const raw = Number(overdueInput ? overdueInput.value : 3);
      const days = Number.isFinite(raw) && raw > 0 ? Math.min(60, Math.round(raw)) : 3;
      if (overdueInput) overdueInput.value = String(days);
      setStatus("儲存中...", false);
      try {
        await db.collection("communities").doc(cid).collection("settings").doc("parcel_config")
          .set({ overdueDays: days, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
        _parcelOverdueDays = days;
        _parcelConfigLoadedCid = String(cid || "").trim();
        setStatus("", false);
        toast("已更新逾期天數");
        if (document.getElementById("parcelList")) {
          const activeBtn = subnavEl ? subnavEl.querySelector("[data-filter].btn-primary") : null;
          const filter = activeBtn ? String(activeBtn.getAttribute("data-filter") || "pending") : "pending";
          renderParcelList(filter, readParcelFilters());
        }
      } catch (err) {
        setStatus("儲存失敗：" + (err && err.message ? err.message : "未知錯誤"), true);
      }
    };
    if (overdueInput) overdueInput.onchange = () => saveOverdueDays();

    // 監聽物流清單
    const unsub = db.collection("communities").doc(cid).collection("settings").doc("parcel_config")
      .onSnapshot(async doc => {
        let couriers = doc.exists ? (doc.data().couriers || []) : [];
        const cfg = doc.exists ? (doc.data() || {}) : {};
        const odRaw = Number(cfg.overdueDays);
        const odDays = Number.isFinite(odRaw) && odRaw > 0 ? Math.min(60, Math.round(odRaw)) : 3;
        _parcelOverdueDays = odDays;
        if (overdueInput && document.activeElement !== overdueInput) overdueInput.value = String(odDays);

        const shelvesArr = Array.isArray(cfg.shelves) ? cfg.shelves : [];
        if (shelvesEl && document.activeElement !== shelvesEl) shelvesEl.value = shelvesArr.join("\n");
        const tplRaw = (cfg.notifyTemplate && typeof cfg.notifyTemplate === "object") ? cfg.notifyTemplate : {};
        if (tplPickupPlace && document.activeElement !== tplPickupPlace) tplPickupPlace.value = String(tplRaw.pickupPlace || "");
        if (tplServiceHours && document.activeElement !== tplServiceHours) tplServiceHours.value = String(tplRaw.serviceHours || "");
        if (tplContactPhone && document.activeElement !== tplContactPhone) tplContactPhone.value = String(tplRaw.contactPhone || "");
        if (tplFooter && document.activeElement !== tplFooter) tplFooter.value = String(tplRaw.footer || "");
        _parcelConfigCache80 = Object.assign({}, _parcelConfigCache80, {
          couriers: Array.isArray(cfg.couriers) ? cfg.couriers : [],
          shelves: shelvesArr,
          notifyTemplate: tplRaw
        });
        
        // 若完全沒有資料，則自動初始化預設清單
        if (!doc.exists || couriers.length === 0) {
          couriers = [...defaultList];
          try {
            await db.collection("communities").doc(cid).collection("settings").doc("parcel_config")
              .set({ couriers, updatedAt: FieldValue.serverTimestamp() }, { merge: true });
            toast("已自動載入預設物流清單");
          } catch (err) {
            console.error("Initialize couriers error:", err);
          }
        }

        renderDefaultCouriers(couriers);
        
        listEl.innerHTML = couriers.map(name => `
          <div class="courier-item" style="display: flex; justify-content: space-between; align-items: center; background: #fff; border: 1px solid var(--border); padding: 10px 12px; border-radius: 10px;">
            <span style="font-weight: 700; font-size: calc(14px * var(--fs, 1));">${escapeHtml(name)}</span>
            <button class="icon-btn danger" style="width: 28px; height: 28px;" data-del-courier="${name}">×</button>
          </div>
        `).join("");
        
        listEl.querySelectorAll("[data-del-courier]").forEach(btn => {
          btn.onclick = () => {
            const name = btn.getAttribute("data-del-courier");
            saveCourier(name, false);
          };
        });
      });

    const oldDetach = detach;
    detach = () => { unsub(); oldDetach(); };

    modal.hidden = false;
  }

  function renderResidentsModule() {
    stopResidentsSubscription();
    stopResidentsOverviewSubscription();
    if (subnavEl) subnavEl.innerHTML = "";
    if (!Array.isArray(state.communities) || state.communities.length === 0) {
      contentEl.innerHTML = `
        <section class="card residents-page chatphone-page">
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg("residents")}</div>
              <div style="min-width:0;">
                <h2>住戶造冊</h2>
                <p>讀取社區資料中...</p>
              </div>
            </div>
            <a class="tag red manual-btn" data-manual="residents" href="${manualViewerHref("residents", "住戶造冊")}" target="_blank" rel="noopener" title="開啟 住戶造冊 操作手冊" aria-label="開啟 住戶造冊 操作手冊">手冊</a>
          </div>
          <div class="card-bd">
            <div class="status">讀取中...</div>
          </div>
        </section>
      `.trim();
      updateFooterActiveNav();
      return;
    }
    const cid = resolveActiveCommunityId();
    const accounts = loadAccounts();
    const c = (accounts.communities || []).find((x) => x && String(x.id || "") === String(cid || "")) || null;
    const cname = c ? String(c.name || "").trim() : "";
    let currentPage = "overview"; // "overview"、"list"、"points"、"pending"

    let communityUnits = normalizeCommunityUnitRows(Array.isArray(c && c.units) ? c.units : []);

    const refreshUnitTotals = () => {
      const el = document.getElementById("unitTotal");
      if (el) el.textContent = `總戶數：${normalizeResidentUnitList(communityUnits).length}`;
    };

    // 戶號資料一律以 communities/{cid} 文件為準，依序嘗試候選社區代碼
    const resolveCommunityUnitRows = async (extraKeys = []) => {
      const candidates = [];
      const addCandidate = (v) => {
        const s = String(v || "").trim();
        if (!s || candidates.includes(s)) return;
        candidates.push(s);
      };
      (Array.isArray(extraKeys) ? extraKeys : []).forEach(addCandidate);
      addCandidate(cid);
      addCandidate(state.currentResidentsCommunityId);
      addCandidate(resolveActiveCommunityId());
      try { addCandidate(sessionStorage.getItem("csp_last_cid")); } catch {}
      for (const slug of candidates) {
        try {
          const doc = await db.collection("communities").doc(String(slug)).get();
          if (!doc || !doc.exists) continue;
          const v = doc.data() || {};
          const rows = normalizeCommunityUnitRows(v.units);
          if (rows.length) return rows;
        } catch {}
      }
      return [];
    };

    // 渲染 subnav 按钮的函数
    const renderSubnav = () => {
      if (!subnavEl) return;
      if (!canCurrentUserUseResidentsSubnav()) {
        subnavEl.innerHTML = "";
        return;
      }
      const t = isCurrentCommunityRole() ? getResidentsSubnavCommunityTabs() : { pending: true, list: true, points: true, chatphone: true };
      const allowPending = !isCurrentCommunityRole() || !!t.pending;
      const allowList = !isCurrentCommunityRole() || !!t.list;
      const allowPoints = !isCurrentCommunityRole() || !!t.points;
      const allowChatphone = !isCurrentCommunityRole() || !!t.chatphone;
      const allowOverview = allowPending || allowList || allowPoints || allowChatphone;
      subnavEl.innerHTML = `
        ${allowOverview ? `<button class="btn btn-sm ${currentPage === "overview" ? "btn-primary" : ""}" type="button" id="btnResidentsOverview">總覽</button>` : ""}
        ${allowPending ? `<button class="btn btn-sm ${currentPage === "pending" ? "btn-primary" : ""}" type="button" id="btnPendingResidents">
          <span class="badge-inline" id="pendingBadge" hidden>0</span>
          待審帳號
        </button>` : ""}
        ${allowList ? `<button class="btn btn-sm ${currentPage === "list" ? "btn-primary" : ""}" type="button" id="btnResidentsList">住戶造冊</button>` : ""}
        ${allowPoints ? `<button class="btn btn-sm ${currentPage === "points" ? "btn-primary" : ""}" type="button" id="btnResidentsPoints">住戶點數</button>` : ""}
        ${allowChatphone ? `<button class="btn btn-sm" type="button" id="btnChatphone">
          <span class="badge-inline" id="chatphoneMissedBadge" hidden>0</span>
          對講機
        </button>` : ""}
        ${isCurrentSystemAdmin() ? `<button class="btn btn-sm" type="button" id="btnResidentsSubnavSettings">設定</button>` : ""}
      `.trim();
      
      // 获取按钮引用
      const overviewBtn = document.getElementById("btnResidentsOverview");
      const pendingBtn = document.getElementById("btnPendingResidents");
      const listBtn = document.getElementById("btnResidentsList");
      const pointsBtn = document.getElementById("btnResidentsPoints");
      const chatphoneBtn = document.getElementById("btnChatphone");
      
      if (overviewBtn) {
        overviewBtn.onclick = () => {
          currentPage = "overview";
          renderPage();
        };
      }
      if (pendingBtn) {
        pendingBtn.onclick = () => {
          currentPage = "pending";
          renderPage();
        };
      }
      if (listBtn) {
        listBtn.onclick = () => {
          currentPage = "list";
          renderPage();
        };
      }
      if (pointsBtn) {
        pointsBtn.onclick = () => {
          currentPage = "points";
          renderPage();
        };
      }
      if (chatphoneBtn) {
        chatphoneBtn.onclick = () => {
          openChatphoneModal90();
        };
      }
      const residentsSubnavSettingsBtn = document.getElementById("btnResidentsSubnavSettings");
      if (residentsSubnavSettingsBtn) {
        residentsSubnavSettingsBtn.onclick = () => {
          openResidentsSubnavSettingsModal80({ communityId: cid, communityName: cname });
        };
      }
      
      // 确保 badges 被正确更新
      if (pendingBtn) ensureResidentsPendingCountSubscription(cid);
      if (chatphoneBtn) ensureIntercomMissedCountSubscription(cid);
    };

    // 初始渲染 subnav
    if (isCurrentCommunityRole()) {
      const t = getResidentsSubnavCommunityTabs();
      const allowed = [];
      if (t.list) allowed.push("list");
      if (t.points) allowed.push("points");
      if (t.pending) allowed.push("pending");
      if (allowed.length) allowed.unshift("overview");
      if (!allowed.includes(currentPage)) currentPage = allowed[0] || "";
    }
    renderSubnav();

    const openChatphoneModal90 = () => {
      const communityId = String(cid || "").trim();
      if (!communityId) return;
      const modal = ensureChatphoneModal80();
      let detach = () => {};
      detach = bindModalClose(modal, () => {
        const frame = modal.querySelector("#chatphoneFrame80");
        if (frame) frame.removeAttribute("src");
        detach();
      });
      const titleEl = modal.querySelector("#chatphoneModalTitle");
      const frame = modal.querySelector("#chatphoneFrame80");
      const base = `${window.location.origin}${window.location.pathname.replace(/[^/]*$/, "")}`;
      const url = new URL("chatphone.html", base);
      url.searchParams.set("c", communityId);
      url.searchParams.set("v", "125");
      if (titleEl) titleEl.textContent = `通話${cname ? `｜${String(cname).trim()}` : ""}`;
      if (frame) frame.src = url.toString();
      modal.hidden = false;
    };

    const renderPage = () => {
      stopResidentsSubscription();
      stopResidentsOverviewSubscription();
      renderSubnav();
      if (isCurrentCommunityRole()) {
        const t = getResidentsSubnavCommunityTabs();
        const allowed = [];
        if (t.list) allowed.push("list");
        if (t.points) allowed.push("points");
        if (t.pending) allowed.push("pending");
        if (allowed.length) allowed.unshift("overview");
        if (allowed.length && !allowed.includes(currentPage)) currentPage = allowed[0];
        if (!allowed.length) {
          contentEl.innerHTML = `
            <section class="card residents-page">
              <div class="card-hd">
                <div class="left">
                  <div class="chip" aria-hidden="true">${iconSvg("residents")}</div>
                  <div style="min-width:0;">
                    <h2>住戶造冊</h2>
                    <p>此帳號未開放任何子分頁</p>
                  </div>
                </div>
              </div>
              <div class="card-bd">
                <div class="status">社區角色目前沒有可使用的子分頁（請由系統管理員至「子分頁設定」開啟）。</div>
              </div>
            </section>
          `.trim();
          updateFooterActiveNav();
          return;
        }
      }
      if (currentPage === "overview") {
        renderResidentsOverview();
      } else if (currentPage === "list") {
        renderResidentsList();
      } else if (currentPage === "points") {
        renderResidentsPoints();
      } else if (currentPage === "pending") {
        renderPendingResidents();
      }
    };

    const renderResidentsList = () => {
      contentEl.innerHTML = `
        <section class="card residents-page">
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg("residents")}</div>
              <div style="min-width:0;">
                <h2>住戶造冊</h2>
                <p>住戶/承租/車位/聯絡方式彙整</p>
              </div>
            </div>
          </div>
          <div class="card-bd">
            <div class="resident-toolbar">
              <div class="resident-total" id="residentTotal">
                <div class="unit-total" id="unitTotal">總戶數：—</div>
                <div class="people-total" id="peopleTotal">總人數：—</div>
              </div>
              <div class="search resident-search">
                <input id="residentSearch" type="text" placeholder="搜尋 戶號 / 姓名 / 手機 / Email / 棟別" autocomplete="off" />
              </div>
              <select id="residentStatusFilter" aria-label="帳號狀態">
                <option value="all">全部狀態</option>
                <option value="enabled">已啟用</option>
                <option value="disabled">未啟用</option>
              </select>
              <button class="btn btn-primary btn-sm" type="button" id="btnAddResident">新增帳號</button>
              <button class="btn btn-warning btn-sm" type="button" id="btnUnits">戶號列表</button>
              <button class="btn btn-sm" type="button" id="btnExportResidents">匯出 Excel</button>
              <button class="btn btn-sm" type="button" id="btnBatchResidents">批次作業</button>
            </div>
            <div class="status" id="residentStatus" hidden></div>
            <div class="resident-list" id="residentList"></div>
          </div>
        </section>
      `.trim();

    const listEl = document.getElementById("residentList");
    const statusEl = document.getElementById("residentStatus");
    const searchEl = document.getElementById("residentSearch");
    const statusFilterEl = document.getElementById("residentStatusFilter");
    const addBtn = document.getElementById("btnAddResident");
    const unitsBtn = document.getElementById("btnUnits");
    const exportBtn = document.getElementById("btnExportResidents");
    const batchBtn = document.getElementById("btnBatchResidents");
    const peopleTotalEl = document.getElementById("peopleTotal");

    const setStatus = (msg, isError) => {
      if (!statusEl) return;
      const t = String(msg || "").trim();
      statusEl.textContent = t;
      statusEl.hidden = !t;
      statusEl.classList.toggle("error", Boolean(isError));
    };

    let residents = [];
    communityUnits = normalizeCommunityUnitRows(Array.isArray(c && c.units) ? c.units : []);
    state.currentResidents = residents;
    state.currentCommunityUnits = communityUnits;
    state.currentResidentsCommunityId = String(cid || "");

    const renderList = () => {
      const q = String(searchEl ? searchEl.value : "").trim().toLowerCase();
      const statusFilter = String(statusFilterEl ? statusFilterEl.value : "all");
      const filtered = residents
        .filter((r) => {
          if (statusFilter === "enabled" && r.enabled === false) return false;
          if (statusFilter === "disabled" && r.enabled !== false) return false;
          return true;
        })
        .filter((r) => {
          if (!q) return true;
          const h = String(r.houseNo || "").toLowerCase();
          const n = String(r.displayName || "").toLowerCase();
          const p = String(r.phone || "").toLowerCase();
          const e = String(r.email || "").toLowerCase();
          const b = String(r.building || r.block || "").toLowerCase();
          return h.includes(q) || n.includes(q) || p.includes(q) || e.includes(q) || b.includes(q);
        });

      if (!listEl) return;
      refreshUnitTotals();
      const isFiltered = Boolean(q) || statusFilter !== "all";
      if (peopleTotalEl) {
        peopleTotalEl.textContent = isFiltered
          ? `篩選結果：${filtered.length} / ${residents.length}`
          : `總人數：${residents.length}`;
      }
      if (!filtered.length) {
        listEl.innerHTML = `<div class="status">${isFiltered ? "沒有符合條件的住戶資料。" : "尚無住戶資料。"}</div>`;
        return;
      }

      listEl.innerHTML = filtered
        .map((r) => {
          const enabled = r.enabled !== false;
          const houseNo = String(r.houseNo || "").trim();
          const subUnit = String(r.subUnit || "").trim();
          const fullUnit = subUnit ? `${houseNo}-${subUnit}` : houseNo;
          const phone = String(r.phone || "").trim();
          const email = String(r.email || "").trim();
          const subParts = [fullUnit, phone, email].filter(Boolean);
          return `
            <div class="resident-item" data-id="${String(r.id || "")}">
              <div class="resident-left">
                <div class="avatar-sm">${avatarHtml(r)}</div>
                <div class="resident-text">
                  <div class="resident-name">${String(r.displayName || "—")}</div>
                  <div class="resident-sub">${subParts.join("｜")}</div>
                </div>
              </div>
              <div class="resident-actions">
                <label class="switch" aria-label="啟用">
                  <input type="checkbox" data-toggle ${enabled ? "checked" : ""} />
                  <span class="slider"></span>
                </label>
                <button class="icon-btn" type="button" data-parking aria-label="車位" title="車位">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M7 4h5.6a4.4 4.4 0 0 1 0 8.8H7V4Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M7 12.8V20" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M17 20V7.5a3.5 3.5 0 0 1 7 0V20" stroke="currentColor" stroke-width="0" />
                    <path d="M14.5 20h5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M14.5 14.5h4.2" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M14.5 11.2h4.2" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M14.5 7.9h4.2" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                  </svg>
                </button>
                <button class="icon-btn" type="button" data-control aria-label="管制" title="管制">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M12 2.5 20 6v6c0 5.2-3.4 9.2-8 9.5C7.4 21.2 4 17.2 4 12V6l8-3.5Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M9 12h6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M12 9v6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                  </svg>
                </button>
                <button class="icon-btn" type="button" data-qr aria-label="編輯QR code" title="編輯QR code">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M4.5 4.5h6v6h-6v-6Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M13.5 4.5h6v6h-6v-6Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M4.5 13.5h6v6h-6v-6Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M13.5 13.5h2.5v2.5h-2.5v-2.5Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M16 16h3.5v3.5H16V16Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                  </svg>
                </button>
                <button class="icon-btn" type="button" data-edit aria-label="編輯" title="編輯">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M4 20h4l10.5-10.5a2 2 0 0 0 0-2.8l-.2-.2a2 2 0 0 0-2.8 0L5 17v3Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M13.5 6.5 17.5 10.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                  </svg>
                </button>
                <button class="icon-btn danger" type="button" data-delete aria-label="刪除" title="刪除">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M9 4h6l1 2h4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M6 6h12l-1 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L6 6Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M10 11v6M14 11v6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                  </svg>
                </button>
              </div>
            </div>
          `.trim();
        })
        .join("");
    };

    const loadResidents = async () => {
      setStatus("讀取中...", false);
      try {
        state.unsubResidents = subscribeUsersByCommunityMembership(String(cid || "default"), (docs) => {
            const list = docs
              .map((d) => {
                const v = d && typeof d.data === "function" ? (d.data() || {}) : {};
                return {
                  id: d.id,
                  role: String(v.role || ""),
                  community: String(v.community || cid || "default"),
                  houseNo: String(v.houseNo || v.unit || ""),
                  subUnit: String(v.subUnit || ""),
                  displayName: String(v.displayName || v.name || ""),
                  email: String(v.email || v.username || ""),
                  phone: String(v.phone || ""),
                  enabled: v.enabled !== false,
                  address: String(v.address || ""),
                  building: String(v.building || v.block || ""),
                  avatarDataUrl: String(v.avatarDataUrl || ""),
                  category: String(v.category || v.residentCategory || ""),
                  residentRoles: Array.isArray(v.residentRoles) ? v.residentRoles : [],
                  residentRoleOther: String(v.residentRoleOther || ""),
                  phoneNormalized: String(v.phoneNormalized || ""),
                  status: String(v.status || ""),
                  qrToken: String(v.qrToken || ""),
                  points: Number(v.points || 0),
                };
              })
              .filter((x) => isResidentRole(x.role) && x.status !== "pending");

            list.sort((a, b) => {
              const ah = String(a.houseNo || "");
              const bh = String(b.houseNo || "");
              if (ah !== bh) return ah.localeCompare(bh, "zh-Hant");
              const as = String(a.subUnit || "");
              const bs = String(b.subUnit || "");
              if (as !== bs) return as.localeCompare(bs, "zh-Hant");
              return String(a.displayName || "").localeCompare(String(b.displayName || ""), "zh-Hant");
            });

            residents = list;
            state.currentResidents = list;
            state.currentCommunityUnits = communityUnits;
            state.currentResidentsCommunityId = String(cid || "");
            state.reloadResidents = loadResidents;
            setStatus("", false);
            renderList();
          }, (err) => {
            const code = String(err && err.code ? err.code : "");
            setStatus(code.includes("permission-denied") ? "沒有權限讀取住戶資料。" : "讀取失敗，請稍後再試。", true);
            residents = [];
            state.currentResidents = [];
            renderList();
          });
      } catch (err) {
        setStatus("系統錯誤，請重整頁面。", true);
      }
    };

    const openChatphoneWindow = () => {
      const communityId = String(cid || "").trim();
      if (!communityId) {
        setStatus("找不到社區資料，無法開啟通話頁面。", true);
        return;
      }
      const modal = ensureChatphoneModal80();
      let detach = () => {};
      detach = bindModalClose(modal, () => {
        const frame = modal.querySelector("#chatphoneFrame80");
        if (frame) frame.removeAttribute("src");
        detach();
      });
      const titleEl = modal.querySelector("#chatphoneModalTitle");
      const frame = modal.querySelector("#chatphoneFrame80");
      const base = `${window.location.origin}${window.location.pathname.replace(/[^/]*$/, "")}`;
      const url = new URL("chatphone.html", base);
      url.searchParams.set("c", communityId);
      url.searchParams.set("v", "125");
      if (titleEl) titleEl.textContent = `通話${cname ? `｜${String(cname).trim()}` : ""}`;
      if (frame) frame.src = url.toString();
      modal.hidden = false;
      setStatus("", false);
    };

    if (searchEl) searchEl.addEventListener("input", renderList);
    if (statusFilterEl) statusFilterEl.addEventListener("change", renderList);
    if (addBtn) addBtn.addEventListener("click", () => openResidentEditor("create"));
    if (unitsBtn) unitsBtn.addEventListener("click", openUnitsEditor);
    if (exportBtn) exportBtn.addEventListener("click", () => exportResidentsExcel80(residents, cname));
    if (batchBtn) {
      batchBtn.addEventListener("click", () => {
        openResidentsBatchHub80({ communityId: cid, list: residents, onDone: loadResidents });
      });
    }

    if (listEl) {
      listEl.addEventListener("click", async (e) => {
        const row = e.target && e.target.closest ? e.target.closest(".resident-item") : null;
        if (!row) return;
        const id = row.getAttribute("data-id");
        const r = residents.find((x) => String(x.id || "") === String(id || "")) || null;
        if (!id || !r) return;

        const avatarHit = e.target && e.target.closest ? e.target.closest(".avatar-sm") : null;
        if (avatarHit) {
          try {
            await intercomStartOutgoingToResident({ communityId: cid, resident: r });
          } catch {
            toast("無法開啟通話(對講)");
          }
          return;
        }

        const parkingBtn = e.target.closest("[data-parking]");
        if (parkingBtn) {
          openResidentParkingModal80({
            cid,
            uid: id,
            unit: String(r.houseNo || r.unit || "").trim(),
            displayName: String(r.displayName || r.email || id),
          });
          return;
        }

        const controlBtn = e.target.closest("[data-control]");
        if (controlBtn) {
          openResidentControlModal80({
            cid,
            uid: id,
            unit: String(r.houseNo || r.unit || "").trim(),
            displayName: String(r.displayName || r.email || id),
          });
          return;
        }

        const qrBtn = e.target.closest("[data-qr]");
        if (qrBtn) {
          openResidentTokenModal80({
            communityId: cid,
            uid: id,
            displayName: String(r.displayName || r.email || id),
            qrToken: String(r.qrToken || "").trim(),
            onSaved: (token) => {
              r.qrToken = token;
              renderList();
            },
          });
          return;
        }

        const editBtn = e.target.closest("[data-edit]");
        if (editBtn) {
          openResidentEditor("edit", r);
          return;
        }
        const delBtn = e.target.closest("[data-delete]");
        if (delBtn) {
          const ok = await (window.nwConfirm ? window.nwConfirm({
            title: "確認刪除",
            message: `確定要刪除住戶「${String(r.displayName || r.email || id)}」？將同時移除其登入帳號與手機查詢索引，刪除後無法復原。`,
            okText: "刪除",
            cancelText: "取消",
            danger: true,
          }) : Promise.resolve(window.confirm("確定要刪除？")));
          if (!ok) return;
          delBtn.disabled = true;
          try {
            const authRes = await deleteResidentAuthAccount80(String(id));
            if (!authRes.ok) {
              const code = String(authRes.reason || "");
              const friendly =
                code === "no-functions-sdk" || code.includes("not-found") || code.includes("unavailable") || code.includes("internal")
                  ? "尚未部署「刪除登入帳號」的雲端函式（請執行 firebase deploy --only functions）。"
                  : `雲端刪除登入帳號失敗（${code || "未知原因"}）。`;
              const proceed = await (window.nwConfirm ? window.nwConfirm({
                title: "無法刪除登入帳號",
                message: `${friendly}\n若仍要繼續，登入帳號會保留，日後同一 Email 可能無法重新新增。是否仍要刪除住戶資料？`,
                okText: "仍要刪除",
                cancelText: "取消",
                danger: true,
              }) : Promise.resolve(window.confirm("仍要刪除住戶資料？")));
              if (!proceed) return;
            }
            // 同步移除手機查詢索引（僅在索引確實指向此住戶時）
            const phoneKey = normalizePhoneDigits(String(r.phone || ""));
            if (phoneKey) {
              try {
                const lk = await db.collection("user_lookup").doc(phoneKey).get();
                if (lk && lk.exists && String((lk.data() || {}).uid || "") === String(id)) {
                  await db.collection("user_lookup").doc(phoneKey).delete();
                }
              } catch {}
            }
            await db.collection("users").doc(String(id)).delete();
            residents = residents.filter((x) => String(x.id || "") !== String(id || ""));
            state.currentResidents = residents;
            renderList();
            toast(authRes.ok ? "已刪除住戶與登入帳號" : "已刪除住戶資料（登入帳號未刪除）");
          } catch {
            toast("刪除失敗");
          } finally {
            delBtn.disabled = false;
          }
        }
      });

      listEl.addEventListener("change", async (e) => {
        const toggle = e.target && e.target.matches ? (e.target.matches("input[data-toggle]") ? e.target : null) : null;
        if (!toggle) return;
        const row = toggle.closest(".resident-item");
        if (!row) return;
        const id = row.getAttribute("data-id");
        const r = residents.find((x) => String(x.id || "") === String(id || "")) || null;
        if (!id || !r) return;
        const prev = Boolean(r.enabled !== false);
        const next = Boolean(toggle.checked);
        toggle.disabled = true;
        try {
          await db.collection("users").doc(String(id)).set(
            { enabled: next, updatedAt: FieldValue.serverTimestamp() },
            { merge: true }
          );
          r.enabled = next;
        } catch {
          toggle.checked = prev;
          toast("更新失敗");
        } finally {
          toggle.disabled = false;
        }
      });
    }

    state.reloadResidents = loadResidents;
    loadResidents();
  };

    /* 總覽：住戶總覽資訊（統計卡片） */
    const renderResidentsOverviewCards = (list) => {
      const el = document.getElementById("residentsOverview");
      if (!el) return;
      const hasData = Array.isArray(list);
      const rows = hasData ? list : [];
      const val = (v) => (hasData ? String(v) : "—");
      const unit = (u) => (hasData ? u : "");
      const enabledCount = rows.filter((r) => r.enabled !== false).length;
      const unitKeySet = new Set(normalizeResidentUnitList(communityUnits).map((x) => String(x || "").trim().toLowerCase()).filter(Boolean));
      const boundCount = rows.filter((r) => {
        const h = String(r.houseNo || "").trim().toLowerCase();
        return Boolean(h) && unitKeySet.has(h);
      }).length;
      const pendingValue = _residentsPendingCountReady ? String(Number(_lastResidentsPendingCount) || 0) : "—";
      const cards = [
        { label: "總戶號", value: val(normalizeResidentUnitList(communityUnits).length), unit: unit("戶"), sub: "社區戶號總數", tone: "" },
        { label: "總住戶", value: val(rows.length), unit: unit("人"), sub: "已建檔住戶帳號", tone: "info" },
        { label: "已啟用", value: val(enabledCount), unit: unit("人"), sub: "可正常登入", tone: "success" },
        { label: "未啟用", value: val(rows.length - enabledCount), unit: unit("人"), sub: "已停用帳號", tone: "muted" },
        { label: "已綁戶號", value: val(hasData ? boundCount : "—"), unit: unit("人"), sub: "戶號存在於社區戶號清單", tone: "" },
        { label: "待審帳號", value: pendingValue, unit: "筆", sub: "待審核註冊申請", tone: "warning", pending: true },
      ];
      el.innerHTML = `
        <div class="residents-overview">
          <div class="residents-overview-head">
            <strong>住戶總覽</strong>
            <span>${escapeHtml(cname)}</span>
          </div>
          <div class="residents-overview-grid">
            ${cards.map((c) => `
              <div class="ro-card${c.tone ? ` tone-${c.tone}` : ""}">
                <div class="ro-label">${escapeHtml(c.label)}</div>
                <div class="ro-value"><span${c.pending ? ' data-overview-pending="1"' : ""}>${escapeHtml(c.value)}</span><span class="ro-unit">${escapeHtml(c.unit)}</span></div>
                <div class="ro-sub">${escapeHtml(c.sub)}</div>
              </div>`).join("")}
          </div>
        </div>
      `.trim();
    };

    const renderResidentsOverview = () => {
      stopResidentsOverviewSubscription();
      contentEl.innerHTML = `
        <section class="card residents-page">
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg("residents")}</div>
              <div style="min-width:0;">
                <h2>住戶造冊</h2>
                <p>住戶總覽</p>
              </div>
            </div>
          </div>
          <div class="card-bd">
            <div id="residentsOverview"></div>
          </div>
        </section>
      `.trim();

      renderResidentsOverviewCards(null);
      ensureResidentsPendingCountSubscription(cid);
      ensureResidentsOverviewSubscription();
    };

    const ensureResidentsOverviewSubscription = () => {
      stopResidentsOverviewSubscription();
      _unsubResidentsOverview = subscribeUsersByCommunityMembership(String(cid || "default"), (docs) => {
        const list = docs
          .map((d) => {
            const v = d && typeof d.data === "function" ? (d.data() || {}) : {};
            return {
              id: d.id,
              role: String(v.role || ""),
              community: String(v.community || cid || "default"),
              houseNo: String(v.houseNo || v.unit || ""),
              subUnit: String(v.subUnit || ""),
              displayName: String(v.displayName || v.name || ""),
              email: String(v.email || v.username || ""),
              phone: String(v.phone || ""),
              enabled: v.enabled !== false,
              status: String(v.status || ""),
            };
          })
          .filter((x) => isResidentRole(x.role) && x.status !== "pending");
        state.currentResidents = list;
        state.currentCommunityUnits = communityUnits;
        state.currentResidentsCommunityId = String(cid || "");
        state.reloadResidents = ensureResidentsOverviewSubscription;
        renderResidentsOverviewCards(list);
      }, () => {
        renderResidentsOverviewCards([]);
      });
    };

    const renderResidentsPoints = () => {
      contentEl.innerHTML = `
        <section class="card residents-page">
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg("residents")}</div>
              <div style="min-width:0;">
                <h2>住戶點數</h2>
                <p>住戶/承租/車位/聯絡方式彙整</p>
              </div>
            </div>
          </div>
          <div class="card-bd">
            <div class="resident-toolbar">
              <div class="resident-total" id="pointsTotal">
                <div class="people-total">總住戶：—</div>
              </div>
              <div class="search resident-search">
                <input id="pointsSearch" type="text" placeholder="搜尋 戶號 / 姓名 / 手機 / Email" autocomplete="off" />
              </div>
              <button class="btn btn-primary btn-sm" type="button" id="btnPointsSettings">點數設定</button>
              <button class="btn btn-sm" type="button" id="btnPointsBatch">批次給點</button>
            </div>
            <div class="status" id="pointsStatus" hidden></div>
            <div class="resident-list" id="pointsList"></div>
          </div>
        </section>
      `.trim();

      const pointsListEl = document.getElementById("pointsList");
      const pointsStatusEl = document.getElementById("pointsStatus");
      const pointsSearchEl = document.getElementById("pointsSearch");
      const pointsTotalEl = document.getElementById("pointsTotal");
      const btnPointsSettings = document.getElementById("btnPointsSettings");
      const btnPointsBatch = document.getElementById("btnPointsBatch");

      const setPointsStatus = (msg, isError) => {
        if (!pointsStatusEl) return;
        const t = String(msg || "").trim();
        pointsStatusEl.textContent = t;
        pointsStatusEl.hidden = !t;
        pointsStatusEl.classList.toggle("error", Boolean(isError));
      };

      let pointsResidents = [];
      let pointsSettings = { sharePoints: true }; // 預設共用

      // 加載點數設定
      const loadPointsSettings = async () => {
        try {
          const currentCid = resolveActiveCommunityId();
          if (!currentCid) return;
          
          const doc = await db.collection("communities").doc(currentCid).get();
          const data = doc.exists ? (doc.data() || {}) : {};
          if (data.pointsSettings && typeof data.pointsSettings === "object") {
            pointsSettings = { ...pointsSettings, ...data.pointsSettings };
          }
        } catch (err) {
          console.error("Load points settings error:", err);
        }
      };

      const getHouseGroupPoints = (houseNo) => {
        if (!pointsSettings.sharePoints) return 0;
        return pointsResidents
          .filter(r => String(r.houseNo || "").trim() === String(houseNo || "").trim())
          .reduce((sum, r) => sum + (Number(r.points) || 0), 0);
      };

      const isMainAccount = (resident) => {
        const subUnit = String(resident.subUnit || "").trim();
        return !subUnit || subUnit === "1";
      };

      const openPointsSettingsModal = () => {
        const modal = ensureModal("pointsSettingsModal", "", "500px");
        let detach = () => {};
        detach = bindModalClose(modal, () => detach());

        const render = () => {
          modal.innerHTML = `
            <div class="modal-backdrop" data-modal-close="1"></div>
            <div class="modal-dialog" role="dialog" aria-modal="true">
              <div class="modal-hd">
                <h3 class="modal-title">點數設定</h3>
                <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
              </div>
              <div class="modal-body">
                <div class="field">
                  <label>點數計算方式</label>
                  <div style="display: flex; flex-direction: column; gap: 12px; margin-top: 8px;">
                    <label style="display: flex; align-items: center; gap: 8px; cursor: pointer;">
                      <input type="radio" name="pointsMode" value="share" ${pointsSettings.sharePoints ? "checked" : ""} />
                      <span>
                        <strong>共用點數</strong>
                        <div style="font-size: calc(12px * var(--fs, 1)); color: var(--muted); margin-top: 4px;">
                          同戶號（例如 A1）的住戶共用點數，以 &lt;戶號&gt;-1 為主帳號顯示，子帳號點數合併計算
                        </div>
                      </span>
                    </label>
                    <label style="display: flex; align-items: center; gap: 8px; cursor: pointer;">
                      <input type="radio" name="pointsMode" value="separate" ${!pointsSettings.sharePoints ? "checked" : ""} />
                      <span>
                        <strong>分開計算</strong>
                        <div style="font-size: calc(12px * var(--fs, 1)); color: var(--muted); margin-top: 4px;">
                          每個住戶獨立計算點數
                        </div>
                      </span>
                    </label>
                  </div>
                </div>
              </div>
              <div class="modal-ft">
                <button class="btn" type="button" data-modal-close="1">取消</button>
                <button class="btn btn-primary" type="button" id="btnSavePointsSettings">儲存</button>
              </div>
            </div>
          `.trim();

          // 綁定單選框事件
          modal.querySelectorAll('input[name="pointsMode"]').forEach(radio => {
            radio.onchange = (e) => {
              pointsSettings.sharePoints = e.target.value === "share";
              console.log("選擇的模式：", pointsSettings.sharePoints ? "共用點數" : "分開計算");
            };
          });

          // 綁定儲存按鈕
          const saveBtn = modal.querySelector("#btnSavePointsSettings");
          if (saveBtn) {
            saveBtn.onclick = async () => {
              try {
                console.log("=== 開始儲存點數設定 ===");
                console.log("當前 pointsSettings.sharePoints =", pointsSettings.sharePoints);
                
                // 獲取當前社區 ID
                const currentCid = resolveActiveCommunityId();
                console.log("儲存點數設定，cid:", currentCid);
                if (!currentCid) {
                  toast("無法取得社區資訊，請重新整理頁面");
                  return;
                }
                
                console.log("準備寫入數據庫...");
                await db.collection("communities").doc(currentCid).set({
                  pointsSettings: {
                    sharePoints: pointsSettings.sharePoints
                  },
                  updatedAt: FieldValue.serverTimestamp()
                }, { merge: true });
                console.log("寫入成功！");
                
                toast("設定已儲存");
                renderPointsList();
                modal.hidden = true;
                detach();
              } catch (err) {
                console.error("=== 儲存失敗 ===");
                console.error("錯誤詳情:", err);
                toast("儲存失敗：" + (err.message || "未知錯誤"));
              }
            };
          }
        };

        render();
        modal.hidden = false;
      };

      // 綁定設定按鈕事件
      if (btnPointsSettings) {
        btnPointsSettings.onclick = openPointsSettingsModal;
      }

      const renderPointsList = () => {
        const q = String(pointsSearchEl ? pointsSearchEl.value : "").trim().toLowerCase();
        let filtered = q
          ? pointsResidents.filter((r) => {
              const h = String(r.houseNo || "").toLowerCase();
              const n = String(r.displayName || "").toLowerCase();
              const p = String(r.phone || "").toLowerCase();
              const e = String(r.email || "").toLowerCase();
              return h.includes(q) || n.includes(q) || p.includes(q) || e.includes(q);
            })
          : pointsResidents;

        if (!pointsListEl) return;
        if (pointsTotalEl) pointsTotalEl.textContent = `總住戶：${pointsResidents.length}`;
        if (!filtered.length) {
          pointsListEl.innerHTML = `<div class="status">尚無住戶資料。</div>`;
          return;
        }

        // 共用模式：每戶僅顯示一個代表（優先主帳號；若該戶沒有主帳號，取第一筆子帳號）
        if (pointsSettings.sharePoints) {
          const representativeByHouse = new Map();
          filtered.forEach((r) => {
            const houseNo = String(r.houseNo || "").trim();
            const key = houseNo || `__id__:${String(r.id || "")}`;
            const cur = representativeByHouse.get(key);
            if (!cur) {
              representativeByHouse.set(key, r);
              return;
            }
            const curMain = isMainAccount(cur);
            const rMain = isMainAccount(r);
            if (rMain && !curMain) {
              representativeByHouse.set(key, r);
              return;
            }
            if (curMain && !rMain) return;
            const cs = String(cur.subUnit || "").trim();
            const rs = String(r.subUnit || "").trim();
            if (rs && (!cs || rs.localeCompare(cs, "zh-Hant") < 0)) representativeByHouse.set(key, r);
          });
          filtered = filtered.filter((r) => {
            const houseNo = String(r.houseNo || "").trim();
            const key = houseNo || `__id__:${String(r.id || "")}`;
            return representativeByHouse.get(key) === r;
          });
        }

        pointsListEl.innerHTML = filtered
          .map((r) => {
            const houseNo = String(r.houseNo || "").trim();
            const subUnit = String(r.subUnit || "").trim();
            const fullUnit = subUnit ? `${houseNo}-${subUnit}` : houseNo;
            let points = Number(r.points) || 0;
            
            // 如果是共用模式，顯示同戶號總和
            if (pointsSettings.sharePoints && houseNo) {
              points = getHouseGroupPoints(houseNo);
            }
            
            return `
              <div class="resident-item" data-id="${String(r.id || "")}">
                <div class="resident-left">
                  <div class="avatar-sm">${avatarHtml(r)}</div>
                  <div class="resident-text">
                    <div class="resident-name">${String(r.displayName || "—")}</div>
                    <div class="resident-sub">${fullUnit}${r.phone ? " | " + r.phone : ""}</div>
                  </div>
                </div>
                <div class="resident-actions" style="gap: 8px; align-items: center;">
                  <div style="font-weight: bold; font-size: calc(16px * var(--fs, 1)); color: var(--primary); min-width: 80px; text-align: right;">${points} 點</div>

                  <button class="icon-btn" type="button" data-action="history" data-id="${String(r.id || "")}" aria-label="紀錄" title="紀錄">
                    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                      <path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10Z" stroke="currentColor" stroke-width="1.7"/>
                      <path d="M12 6v6l4 2" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round" stroke-linecap="round"/>
                    </svg>
                  </button>
                  <button class="icon-btn" type="button" data-action="edit" data-id="${String(r.id || "")}" aria-label="設定" title="設定">
                    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                      <path d="M4 20h4l10.5-10.5a2 2 0 0 0 0-2.8l-.2-.2a2 2 0 0 0-2.8 0L5 17v3Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                      <path d="M13.5 6.5 17.5 10.5" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    </svg>
                  </button>
                </div>
              </div>
            `.trim();
          })
          .join("");

        // 绑定按钮事件
        pointsListEl.querySelectorAll("[data-action]").forEach(btn => {
          btn.onclick = async (e) => {
            const action = btn.getAttribute("data-action");
            const id = btn.getAttribute("data-id");
            const resident = pointsResidents.find(r => r.id === id);
            if (!resident) return;

            if (action === "edit") {
              openPointsEditor(resident);
            } else if (action === "history") {
              openPointsHistory(resident);
            }
          };
        });
      };

      const updatePoints = async (id, newPoints, reason) => {
        try {
          // 获取当前用户信息
          const currentUser = auth.currentUser;
          const operatorName = currentUser ? (currentUser.displayName || currentUser.email || "管理員") : "管理員";
          const operatorUid = currentUser ? currentUser.uid : "";

          // 先获取旧点數
          const doc = await db.collection("users").doc(String(id)).get();
          const oldData = doc.exists ? doc.data() : {};
          const oldPoints = oldData.points || 0;

          // 计算点數变化
          const pointsChange = newPoints - oldPoints;

          // 更新用户点數
          await db.collection("users").doc(String(id)).set({
            points: newPoints,
            updatedAt: FieldValue.serverTimestamp()
          }, { merge: true });

          // 保存点數变更历史纪录
          const historyRecord = {
            userId: String(id),
            communityId: String(cid || "default"),
            oldPoints: oldPoints,
            newPoints: newPoints,
            pointsChange: pointsChange,
            reason: reason || "點數變更",
            operatorName: operatorName,
            operatorUid: operatorUid,
            createdAt: FieldValue.serverTimestamp()
          };

          await db.collection("pointsHistory").add(historyRecord);

          // 如果是共用點數模式，需要更新戶號的總點數
          if (pointsResidents && pointsResidents.length > 0) {
            await saveHousePointsTotals(pointsResidents);
          }

          toast(reason + " 成功");
        } catch (err) {
          toast("操作失敗：" + err.message);
        }
      };

      const openPointsEditor = (resident) => {
        const modal = ensureModal("pointsEditorModal", "", "80%");
        let detach = () => {};
        detach = bindModalClose(modal, () => detach());
        let unsubscribe = () => {};
        let currentPoints = resident.points || 0;

        const render = () => {
          modal.innerHTML = `
            <div class="modal-backdrop" data-modal-close="1"></div>
            <div class="modal-dialog" role="dialog" aria-modal="true">
              <div class="modal-hd" style="display: flex; justify-content: space-between; align-items: center;">
                <h3 class="modal-title">設定點數 - ${String(resident.displayName || resident.email || "住戶")}</h3>
                <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
              </div>
              <div class="modal-body" style="display: flex; flex-direction: column; gap: 20px;">
                <div style="background: var(--bg-soft); padding: 20px; border-radius: 12px; text-align: center;">
                  <div style="color: var(--muted); font-size: calc(14px * var(--fs, 1)); margin-bottom: 8px;">目前點數</div>
                  <div style="font-size: calc(48px * var(--fs, 1)); font-weight: 900; color: var(--primary); line-height: 1;" id="currentPointsDisplay">${currentPoints}</div>
                </div>
                <div>
                  <button class="btn btn-primary" type="button" id="addPointsBtn">新增點數</button>
                </div>
                <div>
                  <h4 style="margin-bottom: 12px; font-weight: bold;">歷史紀錄</h4>
                  <div id="historyList" style="display: flex; flex-direction: column; gap: 8px; max-height: 400px; overflow-y: auto;">
                    <div class="status">載入中...</div>
                  </div>
                </div>
              </div>
              <div class="modal-ft">
                <button class="btn" type="button" data-modal-close="1">關閉</button>
              </div>
            </div>
          `.trim();

          const addBtn = modal.querySelector("#addPointsBtn");
          const historyListEl = modal.querySelector("#historyList");

          // 新增點數按钮
          addBtn.onclick = () => openAddPointsModal();

          // 加载歷史紀錄
          loadHistory(historyListEl);
        };

        const openAddPointsModal = () => {
          const subModal = ensureModal("addPointsSubModal", "", "60%");
          let subDetach = () => {};
          subDetach = bindModalClose(subModal, () => subDetach());

          subModal.innerHTML = `
            <div class="modal-backdrop" data-modal-close="1"></div>
            <div class="modal-dialog" role="dialog" aria-modal="true">
              <div class="modal-hd">
                <h3 class="modal-title">新增點數</h3>
                <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
              </div>
              <form id="addPointsForm">
                <div class="modal-body">
                  <div class="field">
                    <label for="addPointsAmount">增減點數（正數增加，負數扣除）</label>
                    <input id="addPointsAmount" type="number" placeholder="例如：5 或 -3" />
                  </div>
                  <div class="field">
                    <label for="addPointsReason">事由</label>
                    <input id="addPointsReason" type="text" placeholder="請輸入事由" />
                  </div>
                </div>
                <div class="modal-ft">
                  <button class="btn" type="button" data-modal-close="1">取消</button>
                  <button class="btn btn-primary" type="submit">確認</button>
                </div>
              </form>
            </div>
          `.trim();

          const form = subModal.querySelector("#addPointsForm");
          const amountInput = subModal.querySelector("#addPointsAmount");
          const reasonInput = subModal.querySelector("#addPointsReason");

          form.onsubmit = async (e) => {
            e.preventDefault();
            const change = parseInt(amountInput.value, 10) || 0;
            const reason = reasonInput.value || "";
            
            if (!reason) {
              toast("請輸入事由");
              return;
            }
            
            const newPoints = Math.max(0, currentPoints + change);
            await updatePoints(resident.id, newPoints, reason);
            
            // 更新本地顯示
            currentPoints = newPoints;
            const display = modal.querySelector("#currentPointsDisplay");
            if (display) display.textContent = currentPoints;
            
            subModal.hidden = true;
          };

          subModal.hidden = false;
        };

        const loadHistory = (containerEl) => {
          const formatDate = (date) => {
            if (!date) return "—";
            const d = date.toDate ? date.toDate() : new Date(date);
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            const hour = String(d.getHours()).padStart(2, "0");
            const minute = String(d.getMinutes()).padStart(2, "0");
            return `${year}-${month}-${day} ${hour}:${minute}`;
          };

          unsubscribe = db.collection("pointsHistory")
            .where("userId", "==", String(resident.id))
            .limit(50)
            .onSnapshot(
              (snap) => {
                let records = snap.docs.map(d => ({ id: d.id, ...d.data() }));
                
                // 客户端排序
                records.sort((a, b) => {
                  const aTime = a.createdAt && a.createdAt.toMillis ? a.createdAt.toMillis() : 0;
                  const bTime = b.createdAt && b.createdAt.toMillis ? b.createdAt.toMillis() : 0;
                  return bTime - aTime;
                });

                if (!records.length) {
                  containerEl.innerHTML = `<div class="status" style="text-align: center; padding: 32px 0;">目前沒有歷史紀錄</div>`;
                  return;
                }

                containerEl.innerHTML = records.map(record => {
                  const changeClass = record.pointsChange > 0 ? "color: #10b981;" : "color: #ef4444;";
                  const changeText = record.pointsChange > 0 ? `+${record.pointsChange}` : `${record.pointsChange}`;
                  return `
                    <div style="border: 1px solid var(--border); border-radius: 12px; padding: 16px; background: #fff;">
                      <div style="display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 8px;">
                        <div style="font-weight: bold; font-size: calc(14px * var(--fs, 1));">
                          <span style="${changeClass} font-size: calc(18px * var(--fs, 1)); font-weight: 900;">${changeText} 點</span>
                          <span style="color: var(--muted); font-size: calc(12px * var(--fs, 1)); margin-left: 8px;">(${record.oldPoints} → ${record.newPoints})</span>
                        </div>
                        <div style="color: var(--muted); font-size: calc(12px * var(--fs, 1));">${formatDate(record.createdAt)}</div>
                      </div>
                      <div style="color: var(--muted); font-size: calc(13px * var(--fs, 1)); margin-bottom: 4px;">${record.reason}</div>
                      <div style="color: var(--muted); font-size: calc(12px * var(--fs, 1));">操作人員：${record.operatorName || "—"}</div>
                    </div>
                  `;
                }).join("");
              },
              (err) => {
                console.error("Failed to load points history:", err);
                containerEl.innerHTML = `<div class="status error">載入失敗：${err.message}</div>`;
              }
            );
        };

        const originalDetach = detach;
        detach = () => {
          unsubscribe();
          originalDetach();
        };

        render();
        modal.hidden = false;
      };

      const openPointsHistory = (resident) => {
        const modal = ensureModal("pointsHistoryModal", "", "90%");
        let unsubscribe = () => {};
        const detach = bindModalClose(modal, () => {
          unsubscribe();
          detach();
        });

        modal.innerHTML = `
          <div class="modal-backdrop" data-modal-close="1"></div>
          <div class="modal-dialog" role="dialog" aria-modal="true">
            <div class="modal-hd">
              <h3 class="modal-title">點數紀錄 - ${String(resident.displayName || resident.email || "住戶")}</h3>
              <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
            </div>
            <div class="modal-body" style="max-height: 70vh; overflow-y: auto;">
              <div id="historyStatus" class="status" style="margin-bottom: 16px;">讀取中...</div>
              <div id="historyList"></div>
            </div>
          </div>
        `.trim();

        const statusEl = modal.querySelector("#historyStatus");
        const listEl = modal.querySelector("#historyList");

        const formatDate = (date) => {
          if (!date) return "—";
          const d = date.toDate ? date.toDate() : new Date(date);
          const year = d.getFullYear();
          const month = String(d.getMonth() + 1).padStart(2, "0");
          const day = String(d.getDate()).padStart(2, "0");
          const hour = String(d.getHours()).padStart(2, "0");
          const minute = String(d.getMinutes()).padStart(2, "0");
          return `${year}-${month}-${day} ${hour}:${minute}`;
        };

        // 监听历史纪录变化
        unsubscribe = db.collection("pointsHistory")
          .where("userId", "==", String(resident.id))
          .limit(50)
          .onSnapshot(
            (snap) => {
              let records = snap.docs.map(d => ({ id: d.id, ...d.data() }));
              
              // 在客户端排序
              records.sort((a, b) => {
                const aTime = a.createdAt && a.createdAt.toMillis ? a.createdAt.toMillis() : 0;
                const bTime = b.createdAt && b.createdAt.toMillis ? b.createdAt.toMillis() : 0;
                return bTime - aTime; // 降序
              });

              if (statusEl) {
                statusEl.hidden = true;
              }

              if (!records.length) {
                if (listEl) {
                  listEl.innerHTML = `<div class="status" style="text-align: center; padding: 32px 0;">目前沒有點數變更紀錄</div>`;
                }
                return;
              }

              if (listEl) {
                listEl.innerHTML = `
                  <div style="display: grid; gap: 12px;">
                    ${records.map(record => {
                      const changeClass = record.pointsChange > 0 ? "success" : "danger";
                      const changeText = record.pointsChange > 0 ? `+${record.pointsChange}` : `${record.pointsChange}`;
                      return `
                        <div style="border: 1px solid var(--border); border-radius: 12px; padding: 16px; background: #fff;">
                          <div style="display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 8px;">
                            <div style="font-weight: bold; font-size: calc(14px * var(--fs, 1));">
                              <span style="color: ${record.pointsChange > 0 ? '#10b981' : '#ef4444'}; font-size: calc(18px * var(--fs, 1)); font-weight: 900;">${changeText} 點</span>
                              <span style="color: var(--muted); font-size: calc(12px * var(--fs, 1)); margin-left: 8px;">(${record.oldPoints} → ${record.newPoints})</span>
                            </div>
                            <div style="color: var(--muted); font-size: calc(12px * var(--fs, 1));">${formatDate(record.createdAt)}</div>
                          </div>
                          <div style="color: var(--muted); font-size: calc(13px * var(--fs, 1)); margin-bottom: 4px;">${record.reason}</div>
                          <div style="color: var(--muted); font-size: calc(12px * var(--fs, 1));">操作人員：${record.operatorName || "—"}</div>
                        </div>
                      `;
                    }).join("")}
                  </div>
                `;
              }
            },
            (err) => {
              console.error("Failed to load points history:", err);
              if (statusEl) {
                statusEl.textContent = "載入失敗：" + err.message;
                statusEl.classList.add("error");
                statusEl.hidden = false;
              }
            }
          );

        modal.hidden = false;
      };

      // 計算並保存每個戶號的總點數
      const saveHousePointsTotals = async (list) => {
        try {
          console.log("saveHousePointsTotals - 開始處理，cid:", cid, "list長度:", list.length);
          
          const housePoints = {};
          list.forEach((r) => {
            const houseNo = String(r.houseNo || "").trim();
            const points = Number(r.points || 0);
            console.log("saveHousePointsTotals - 住戶:", r.displayName, "houseNo:", houseNo, "points:", points);
            
            if (houseNo) {
              if (!housePoints[houseNo]) {
                housePoints[houseNo] = 0;
              }
              housePoints[houseNo] += points;
            }
          });
          
          console.log("saveHousePointsTotals - 計算完成，housePoints:", housePoints);
          
          await db.collection("communities").doc(cid).set({
            housePoints: housePoints,
            updatedAt: FieldValue.serverTimestamp()
          }, { merge: true });
          
          console.log("saveHousePointsTotals - 已保存戶號點數總計:", housePoints);
        } catch (e) {
          console.error("saveHousePointsTotals - 保存失敗:", e);
        }
      };

      // 批次給點：勾選多位住戶後統一增減點數
      const openResidentsBatchPoints80 = () => {
        const modal = ensureModal("residentsBatchPointsModal80", "modal-residents-batch", "min(800px, 96vw)");
        let detach = () => {};
        let busy = false;
        detach = bindModalClose(modal, () => { if (!busy) detach(); });

        const people = pointsResidents.slice();
        const selected = new Set();
        let visibleIds = [];

        modal.innerHTML = `
          <div class="modal-backdrop" data-modal-close="1"></div>
          <div class="modal-dialog" role="dialog" aria-modal="true">
            <div class="modal-hd">
              <h3 class="modal-title">批次給點</h3>
              <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
            </div>
            <div class="modal-body">
              <div class="resident-toolbar" style="margin-bottom:10px;">
                <div class="search resident-search">
                  <input id="rbPointsSearch" type="text" placeholder="搜尋 戶號 / 姓名 / 手機 / Email" autocomplete="off" />
                </div>
                <label class="rb-select-all"><input type="checkbox" id="rbPointsAll" /> 全選</label>
              </div>
              <div class="resident-list" id="rbPointsList" style="max-height:320px;overflow:auto;"></div>
              <div class="field" style="margin-top:12px;">
                <label for="rbPointsAmount">增減點數（正數增加、負數扣除）</label>
                <input id="rbPointsAmount" type="number" placeholder="例如：5 或 -3" />
              </div>
              <div class="field" style="margin-top:8px;">
                <label for="rbPointsReason">事由</label>
                <input id="rbPointsReason" type="text" placeholder="請輸入事由" />
              </div>
              <div class="status" id="rbPointsInfo" hidden></div>
            </div>
            <div class="modal-ft">
              <button class="btn" type="button" data-modal-close="1">關閉</button>
              <button class="btn btn-primary" type="button" id="rbPointsApply">套用</button>
            </div>
          </div>
        `.trim();

        const listEl = modal.querySelector("#rbPointsList");
        const searchEl = modal.querySelector("#rbPointsSearch");
        const allEl = modal.querySelector("#rbPointsAll");
        const amountEl = modal.querySelector("#rbPointsAmount");
        const reasonEl = modal.querySelector("#rbPointsReason");
        const infoEl = modal.querySelector("#rbPointsInfo");
        const applyBtn = modal.querySelector("#rbPointsApply");

        const setInfo = (msg, isError) => {
          if (!infoEl) return;
          const t = String(msg || "").trim();
          infoEl.textContent = t;
          infoEl.hidden = !t;
          infoEl.classList.toggle("error", Boolean(isError));
        };

        const syncAllState = () => {
          if (!allEl) return;
          const allSelected = visibleIds.length > 0 && visibleIds.every((id) => selected.has(id));
          allEl.checked = allSelected;
          allEl.indeterminate = !allSelected && visibleIds.some((id) => selected.has(id));
          setInfo(selected.size ? `已勾選 ${selected.size} 位` : "", false);
        };

        const renderList = () => {
          if (!listEl) return;
          const q = String(searchEl ? searchEl.value : "").trim().toLowerCase();
          const rows = people.filter((r) => {
            if (!q) return true;
            return [r.houseNo, r.subUnit, r.displayName, r.phone, r.email]
              .some((v) => String(v || "").toLowerCase().includes(q));
          });
          visibleIds = rows.map((r) => String(r.id || ""));
          if (!rows.length) {
            listEl.innerHTML = `<div class="status">沒有符合的住戶。</div>`;
            syncAllState();
            return;
          }
          listEl.innerHTML = rows.map((r) => {
            const unit = [r.houseNo, r.subUnit].filter(Boolean).join("-");
            const id = String(r.id || "");
            const points = Number(r.points || 0);
            return `
              <label class="resident-item" style="cursor:pointer;">
                <div class="resident-left">
                  <input type="checkbox" data-uid="${escapeHtml(id)}" ${selected.has(id) ? "checked" : ""} />
                  <div class="avatar-sm">${avatarHtml(r)}</div>
                  <div class="resident-text">
                    <div class="resident-name">${escapeHtml(r.displayName || "—")}</div>
                    <div class="resident-sub">${escapeHtml(unit || "—")}｜${escapeHtml(r.phone || r.email || "")}</div>
                  </div>
                </div>
                <div style="font-weight:900;color:var(--primary);white-space:nowrap;">${points} 點</div>
              </label>`;
          }).join("");

          listEl.querySelectorAll("input[data-uid]").forEach((cb) => {
            cb.addEventListener("change", () => {
              const id = cb.getAttribute("data-uid");
              if (!id) return;
              if (cb.checked) selected.add(id);
              else selected.delete(id);
              syncAllState();
            });
          });
          syncAllState();
        };

        const apply = async () => {
          if (busy) return;
          const change = parseInt(amountEl ? amountEl.value : "", 10);
          if (!Number.isFinite(change) || change === 0) { setInfo("請輸入不為 0 的點數增減值。", true); return; }
          const reason = String(reasonEl ? reasonEl.value : "").trim();
          if (!reason) { setInfo("請輸入事由。", true); return; }
          const ids = Array.from(selected);
          if (!ids.length) { setInfo("請先勾選住戶。", true); return; }
          const proceed = await (window.nwConfirm ? window.nwConfirm({
            title: "確認批次給點",
            message: `將對 ${ids.length} 位住戶${change > 0 ? `增加 ${change}` : `扣除 ${Math.abs(change)}`} 點，是否繼續？`,
            okText: "確認",
            cancelText: "取消",
          }) : Promise.resolve(window.confirm(`將對 ${ids.length} 位住戶調整 ${change} 點？`)));
          if (!proceed) return;

          busy = true;
          if (applyBtn) applyBtn.disabled = true;
          const currentUser = auth.currentUser;
          const operatorName = currentUser ? (currentUser.displayName || currentUser.email || "管理員") : "管理員";
          const operatorUid = currentUser ? currentUser.uid : "";
          let success = 0;
          const failures = [];

          for (let i = 0; i < ids.length; i += 1) {
            const id = ids[i];
            setInfo(`套用中 ${i + 1}/${ids.length}`, false);
            try {
              const doc = await db.collection("users").doc(id).get();
              const oldPoints = Number((doc.data() || {}).points || 0);
              const newPoints = Math.max(0, oldPoints + change);
              await db.collection("users").doc(id).set(
                { points: newPoints, updatedAt: FieldValue.serverTimestamp() },
                { merge: true }
              );
              await db.collection("pointsHistory").add({
                userId: id,
                communityId: String(cid || "default"),
                oldPoints,
                newPoints,
                pointsChange: newPoints - oldPoints,
                reason,
                operatorName,
                operatorUid,
                createdAt: FieldValue.serverTimestamp(),
              });
              const local = pointsResidents.find((x) => String(x.id || "") === id);
              if (local) local.points = newPoints;
              success += 1;
            } catch (err) {
              failures.push(id);
            }
          }

          busy = false;
          if (applyBtn) applyBtn.disabled = false;
          try { await saveHousePointsTotals(pointsResidents); } catch {}
          renderPointsList();
          const summary = `完成：成功 ${success} 筆${failures.length ? `、失敗 ${failures.length} 筆` : ""}。`;
          setInfo(summary, failures.length > 0);
          if (success) toast(`已批次調整 ${success} 位住戶點數`);
        };

        if (searchEl) searchEl.addEventListener("input", renderList);
        if (allEl) {
          allEl.addEventListener("change", () => {
            if (allEl.checked) visibleIds.forEach((id) => selected.add(id));
            else visibleIds.forEach((id) => selected.delete(id));
            renderList();
          });
        }
        if (applyBtn) applyBtn.addEventListener("click", apply);

        renderList();
        modal.hidden = false;
      };

      if (btnPointsBatch) btnPointsBatch.onclick = openResidentsBatchPoints80;

      // 加载住户数据（包含点数字段）
      const loadPointsResidents = async () => {
        setPointsStatus("讀取中...", false);
        try {
          state.unsubResidents = subscribeUsersByCommunityMembership(String(cid || "default"), (docs) => {
              const list = docs
                .map((d) => {
                  const v = d && typeof d.data === "function" ? (d.data() || {}) : {};
                  return {
                    id: d.id,
                    role: String(v.role || ""),
                    houseNo: String(v.houseNo || v.unit || ""),
                    subUnit: String(v.subUnit || ""),
                    displayName: String(v.displayName || v.name || ""),
                    email: String(v.email || v.username || ""),
                    phone: String(v.phone || ""),
                    enabled: v.enabled !== false,
                    avatarDataUrl: String(v.avatarDataUrl || ""),
                    status: String(v.status || ""),
                    points: v.points || 0
                  };
                })
                .filter((x) => isResidentRole(x.role) && x.status !== "pending");

              list.sort((a, b) => {
                const ah = String(a.houseNo || "");
                const bh = String(b.houseNo || "");
                if (ah !== bh) return ah.localeCompare(bh, "zh-Hant");
                const as = String(a.subUnit || "");
                const bs = String(b.subUnit || "");
                if (as !== bs) return as.localeCompare(bs, "zh-Hant");
                return String(a.displayName || "").localeCompare(String(b.displayName || ""), "zh-Hant");
              });

              pointsResidents = list;
              setPointsStatus("", false);
              renderPointsList();
              
              // 保存每個戶號的總點數
              saveHousePointsTotals(list);
            }, (err) => {
              const code = String(err && err.code ? err.code : "");
              setPointsStatus(code.includes("permission-denied") ? "沒有權限讀取住戶資料。" : "讀取失敗，請稍後再試。", true);
              pointsResidents = [];
              renderPointsList();
            });
        } catch (err) {
          setPointsStatus("系統錯誤，請重整頁面。", true);
        }
      };

      if (pointsSearchEl) {
        pointsSearchEl.addEventListener("input", renderPointsList);
      }

      loadPointsSettings().then(() => {
        loadPointsResidents();
      });
    };

    const renderPendingResidents = () => {
      contentEl.innerHTML = `
        <section class="card residents-page">
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg("residents")}</div>
              <div style="min-width:0;">
                <h2>待審帳號</h2>
                <p>住戶/承租/車位/聯絡方式彙整</p>
              </div>
            </div>
          </div>
          <div class="card-bd">
            <div class="status" id="pendingResidentsStatus" hidden></div>
            <div class="resident-list" id="pendingResidentsList"></div>
          </div>
        </section>
      `.trim();

      const listEl = document.getElementById("pendingResidentsList");
      const statusEl = document.getElementById("pendingResidentsStatus");

      const setStatus = (msg, isError) => {
        if (!statusEl) return;
        const t = String(msg || "").trim();
        statusEl.textContent = t;
        statusEl.hidden = !t;
        statusEl.classList.toggle("error", Boolean(isError));
      };

      const renderList = (list) => {
        if (!listEl) return;
        if (!list.length) {
          listEl.innerHTML = `<div class="status">目前沒有帳號申請紀錄。</div>`;
          return;
        }

        listEl.innerHTML = list.map((r) => {
          const houseNo = String(r.houseNo || "").trim();
          const phone = String(r.phone || "").trim();
          const email = String(r.email || "").trim();
          const subParts = [houseNo, phone, email].filter(Boolean);
          const isPending = r.status === "pending";
          const statusLabel = isPending ? "待審核" : (r.status === "approved" ? "已核准" : r.status);
          const statusClass = isPending ? "warning" : "success";

          return `
            <div class="resident-item" data-id="${String(r.id || "")}">
              <div class="resident-left">
                <div class="avatar-sm">${avatarHtml(r)}</div>
                <div class="resident-text">
                  <div class="resident-name">
                    ${String(r.displayName || "—")}
                    <span class="status-chip ${statusClass}">${statusLabel}</span>
                  </div>
                  <div class="resident-sub">${subParts.join("｜")}</div>
                </div>
              </div>
              <div class="resident-actions">
                ${isPending ? `
                  <button class="btn btn-primary btn-sm" type="button" data-approve title="核准">核准</button>
                  <button class="btn btn-sm danger" type="button" data-reject title="刪除">刪除</button>
                ` : `
                  <button class="btn btn-sm" type="button" disabled>已處理</button>
                `}
              </div>
            </div>
          `.trim();
        }).join("");

        // 綁定核准/拒絕事件
        listEl.querySelectorAll(".resident-item").forEach(item => {
          const id = item.getAttribute("data-id");
          const r = list.find(x => x.id === id);
          if (!r) return;

          const avatarEl = item.querySelector(".avatar-sm");
          if (avatarEl) {
            avatarEl.style.cursor = "pointer";
            avatarEl.onclick = (ev) => {
              if (ev) {
                try { ev.preventDefault(); } catch {}
                try { ev.stopPropagation(); } catch {}
              }
              if (String(r.status || "").trim() === "pending") {
                toast("此帳號尚未核准，無法通話");
                return;
              }
              intercomStartOutgoingToResident({ communityId: cid, resident: r }).catch(() => toast("無法開啟通話(對講)"));
            };
          }

          if (r.status !== "pending") return;
          
          item.querySelector("[data-approve]").onclick = async () => {
            const ok = await (window.nwConfirm ? window.nwConfirm({
              title: "核准帳號",
              message: `是否核准「${r.displayName}」的住戶帳號申請並建立正式登入帳號？`,
              okText: "核准並建立",
              cancelText: "取消"
            }) : Promise.resolve(confirm("是否核准？")));
            
            if (ok) {
              const defaultPwd = normalizePhoneDigits(r.phone);
              const password = await promptTextModal80({
                id: "approveResidentPwdModal80",
                title: "設定初始登入密碼",
                label: `「${String(r.displayName || r.email || "")}」的登入密碼`,
                hint: "申請資料只保留密碼雜湊、無法還原。請輸入申請人提供的密碼（或直接以手機號碼作為初始密碼）。此密碼僅用於建立登入帳號，不會儲存到資料庫。",
                defaultValue: defaultPwd,
                okText: "核准並建立",
                type: "text",
                minLength: 6
              });
              if (!password) return;
              let createdAuth = null;
              try {
                toast("正在建立帳號...");
                const email = String(r.email || "").trim().toLowerCase();
                const phone = normalizePhoneDigits(r.phone);

                if (!email || !password) throw new Error("缺少必要的 Email 或密碼資訊");

                // 1. 在 Firebase Auth 建立帳號
                createdAuth = await createAuthUser(email, password);
                const newUid = createdAuth.uid;

                // 2. 將資料轉移至以 UID 為鍵的文件，並更新狀態
                const payload = {
                  ...r,
                  id: newUid,
                  uid: newUid,
                  username: email,
                  status: "approved",
                  enabled: true,
                  updatedAt: FieldValue.serverTimestamp()
                };
                delete payload.password; // 不在 Firestore 儲存明文密碼
                delete payload.passwordHash; // 舊申請的雜湊不沿用，稍後以新密碼重算
                delete payload.passwordPlain;

                // 密碼 Hash 處理
                if (typeof sha256Hex === "function") {
                  payload.passwordHash = await sha256Hex(password);
                  payload.passwordHashAlg = "SHA-256";
                  payload.passwordUpdatedAt = FieldValue.serverTimestamp();
                }

                await db.collection("users").doc(newUid).set(payload, { merge: true });

                // 3. 更新搜尋索引
                if (typeof upsertUserLookup === "function") {
                  const accounts = loadAccounts();
                  const c = (accounts.communities || []).find((x) => x && String(x.id || "") === String(cid || "")) || null;
                  const communityCode = c ? String(c.username || "") : "";
                  await upsertUserLookup({ 
                    phoneNormalized: phone, 
                    email, 
                    phone, 
                    uid: newUid, 
                    community: cid, 
                    communityCode, 
                    role: "住戶" 
                  });
                }

                // 4. 刪除原本的申請紀錄
                if (id !== newUid) {
                  await db.collection("users").doc(id).delete();
                }

                toast("帳號核准成功並已建立");
              } catch (err) {
                console.error("Approval error:", err);
                const code = String(err && err.code ? err.code : "");
                const msg =
                  code.includes("auth/email-already-in-use") ? "此電子郵件已被使用。" :
                  code.includes("auth/weak-password") ? "密碼強度不足。" :
                  "核准失敗：" + err.message;
                toast(msg);
              } finally {
                if (createdAuth && createdAuth.auth) {
                  try {
                    await createdAuth.auth.signOut();
                  } catch {}
                }
              }
            }
          };

          item.querySelector("[data-reject]").onclick = async () => {
            const ok = await (window.nwConfirm ? window.nwConfirm({
              title: "刪除申請",
              message: `是否刪除「${r.displayName}」的住戶帳號申請紀錄？`,
              okText: "確認刪除",
              cancelText: "取消",
              danger: true
            }) : Promise.resolve(confirm("是否刪除？")));
            
            if (ok) {
              try {
                await db.collection("users").doc(id).delete();
                toast("已刪除申請紀錄");
              } catch (err) {
                toast("操作失敗：" + err.message);
              }
            }
          };
        });
      };

      setStatus("讀取中...", false);
      state.unsubResidents = db.collection("users")
        .where("community", "==", cid)
        .where("role", "==", "resident")
        .where("status", "==", "pending")
        .onSnapshot((snap) => {
          let list = snap.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          
          // 在前端進行排序
          list.sort((a, b) => {
            const tA = a.createdAt ? (a.createdAt.toMillis ? a.createdAt.toMillis() : a.createdAt) : 0;
            const tB = b.createdAt ? (b.createdAt.toMillis ? b.createdAt.toMillis() : b.createdAt) : 0;
            return tB - tA; // 降冪排序
          });

          setStatus("", false);
          renderList(list);
        }, (err) => {
          setStatus("讀取失敗：" + err.message, true);
        });
    };

    const openResidentEditor = async (mode, resident) => {
      const activeResidentsCid = String(state.currentResidentsCommunityId || resolveActiveCommunityId() || "default");
      const getResidents = () => (Array.isArray(state.currentResidents) ? state.currentResidents : []);
      const getCommunityUnits = () => (Array.isArray(state.currentCommunityUnits) ? state.currentCommunityUnits : []);
      const modal = ensureResidentEditorModal();
      let detach = () => {};
      detach = bindModalClose(modal, () => detach());
      const titleEl = modal.querySelector("#residentModalTitle");
      const form = modal.querySelector("#residentModalForm");
      const st = modal.querySelector("#residentModalStatus");
      const roleNameEl = modal.querySelector("#residentRoleName");
      const inputCategory = modal.querySelector("#modal_r_category");
      const inputCommunity = modal.querySelector("#modal_r_community");
      const inputUnit = modal.querySelector("#modal_r_unit");
      const inputSubUnit = modal.querySelector("#modal_r_sub_unit");
      const inputName = modal.querySelector("#modal_r_name");
      const inputEmail = modal.querySelector("#modal_r_email");
      const inputPhone = modal.querySelector("#modal_r_phone");
      const inputPassword = modal.querySelector("#modal_r_password");
      const inputAddr = modal.querySelector("#modal_r_address");
      const inputBuilding = modal.querySelector("#modal_r_building");
      const inputEnabled = modal.querySelector("#modal_r_enabled");
      const unitMatchBadge = modal.querySelector("#unitMatchBadge");
      const avatarUploader = modal.querySelector("#residentAvatarUploader");
      const avatarInput = modal.querySelector("#residentAvatarInput");
      const avatarPreview = modal.querySelector("#residentAvatarPreview");
      const avatarPlaceholder = modal.querySelector("#residentAvatarPlaceholder");
      const rolesWrap = modal.querySelector("#modal_r_roles");
      const roleOtherChk = modal.querySelector("#modal_r_role_other_chk");
      const roleOtherText = modal.querySelector("#modal_r_role_other_text");
      const cancelBtn = modal.querySelector("#btnCancelResidentModal");
      const closeBtn = modal.querySelector("#btnCloseResidentModal");
      const submitBtn = modal.querySelector("#btnSubmitResidentModal");
      const btnUnlockCommunity = modal.querySelector("#btnUnlockCommunity");

      const setModalStatus = (msg, isError) => {
        if (!st) return;
        const t = String(msg || "").trim();
        st.textContent = t;
        st.hidden = !t;
        st.classList.toggle("error", Boolean(isError));
      };

      const ensureCommunityUnitsLoaded = async () => {
        const current = getCommunityUnits();
        const hasMeta = Array.isArray(current) && current.some((x) => x && typeof x === "object" && (String(x.building || x.block || "").trim() || String(x.address || "").trim()));
        if (hasMeta) return;
        const cid = normalizeText(inputCommunity ? inputCommunity.value : activeResidentsCid) || activeResidentsCid || "default";
        try {
          const doc = await db.collection("communities").doc(String(cid)).get();
          const v = doc && doc.exists ? (doc.data() || {}) : {};
          state.currentCommunityUnits = normalizeCommunityUnitRows(v.units);
        } catch {}
      };

      const findCommunityUnitMeta = (unit) => {
        const unitVal = normalizeText(unit);
        if (!unitVal) return null;
        const found = getCommunityUnits().find((u) => {
          const uid = (typeof u === "object" && u !== null) ? String(u.id || "") : String(u || "");
          return uid.trim().toLowerCase() === unitVal.toLowerCase();
        });
        return (found && typeof found === "object") ? found : null;
      };

      const syncResidentUnitMeta = ({ forceAddress = false, forceBuilding = false } = {}) => {
        const found = findCommunityUnitMeta(inputUnit ? inputUnit.value : "");
        if (!found) return;
        if (inputAddr && (forceAddress || !inputAddr.value.trim()) && String(found.address || "").trim()) {
          inputAddr.value = String(found.address || "").trim();
        }
        if (inputBuilding && (forceBuilding || !inputBuilding.value.trim()) && String(found.building || found.block || "").trim()) {
          inputBuilding.value = String(found.building || found.block || "").trim();
        }
      };

      const isEdit = mode === "edit";
      const data = resident || {};
      if (titleEl && titleEl.childNodes && titleEl.childNodes.length >= 3) {
        titleEl.childNodes[0].nodeValue = isEdit ? "編輯 " : "新增 ";
        titleEl.childNodes[2].nodeValue = " 帳號";
      }
      if (roleNameEl) roleNameEl.textContent = "住戶";
      if (inputCategory) inputCategory.value = isEdit ? String(data.category || "住戶") : "住戶";
      
      if (inputCommunity) {
        const currentCid = isEdit ? String(data.community || activeResidentsCid || "default") : String(activeResidentsCid || "default");
        const options = 
          `<option value="" selected>全部</option>` + 
          (state.communities || []).map(c => 
            `<option value="${c.id}">${escapeHtml(c.name)}</option>`
          ).join("");
        inputCommunity.innerHTML = options;
        inputCommunity.value = isEdit ? currentCid : "";
        inputCommunity.disabled = true;
        
        if (btnUnlockCommunity) {
          btnUnlockCommunity.classList.remove("unlocked");
          btnUnlockCommunity.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:18px;height:18px;"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>`;
          btnUnlockCommunity.onclick = () => {
            const isLocked = inputCommunity.disabled;
            inputCommunity.disabled = !isLocked;
            btnUnlockCommunity.classList.toggle("unlocked", isLocked);
            if (isLocked) {
              // 切換為解鎖狀態
              btnUnlockCommunity.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:18px;height:18px;"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path><path d="M12 11v4"></path><path d="M12 11h.01"></path></svg>`;
              toast("已解鎖所屬社區變更");
            } else {
              // 切換為鎖定狀態
              btnUnlockCommunity.innerHTML = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:18px;height:18px;"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>`;
            }
          };
        }
      }
      if (inputUnit) inputUnit.value = isEdit ? String(data.houseNo || "") : "";
      if (inputSubUnit) inputSubUnit.value = isEdit ? String(data.subUnit || "") : "";
      if (inputName) inputName.value = isEdit ? String(data.displayName || "") : "";
      if (inputEmail) inputEmail.value = isEdit ? String(data.email || "") : "";
      if (inputPhone) inputPhone.value = isEdit ? String(data.phone || "") : "";
      if (inputAddr) inputAddr.value = isEdit ? String(data.address || "") : "";
      if (inputBuilding) inputBuilding.value = isEdit ? String(data.building || data.block || "") : "";
      if (inputEnabled) inputEnabled.value = String((isEdit ? data.enabled !== false : true) ? "true" : "false");
      await ensureCommunityUnitsLoaded();
      syncResidentUnitMeta();
      if (inputPassword) inputPassword.value = "";
      if (inputEmail) inputEmail.disabled = Boolean(isEdit);
      if (submitBtn) submitBtn.textContent = isEdit ? "更新" : "建立";
      setModalStatus("", false);
      modal.hidden = false;
      requestAnimationFrame(() => {
        if (inputUnit) inputUnit.focus();
      });

      let unitTouched = false;
      let avatarFile = null;
      let avatarPreviewData = "";

      const setAvatarPreview = (dataUrl) => {
        avatarPreviewData = String(dataUrl || "");
        if (avatarPreview) {
          avatarPreview.src = avatarPreviewData || "";
          avatarPreview.style.display = avatarPreviewData ? "block" : "none";
        }
        if (avatarPlaceholder) avatarPlaceholder.style.display = avatarPreviewData ? "none" : "block";
      };

      const syncOtherRoleInput = () => {
        if (!roleOtherText || !roleOtherChk) return;
        roleOtherText.hidden = !roleOtherChk.checked;
        if (!roleOtherChk.checked) roleOtherText.value = "";
      };

      const readResidentRoles = () => {
        const picked = new Set();
        if (rolesWrap) {
          rolesWrap.querySelectorAll("input[type=\"checkbox\"]").forEach((el) => {
            if (el.checked) picked.add(String(el.value || ""));
          });
        }
        const otherEnabled = roleOtherChk && roleOtherChk.checked;
        const otherText = normalizeText(roleOtherText ? roleOtherText.value : "");
        const roles = Array.from(picked).filter(Boolean);
        const extra = otherEnabled ? otherText : "";
        return { roles, extra };
      };

      const updateUnitMatch = () => {
        if (!unitMatchBadge || !inputUnit) return;
        if (!unitTouched) {
          unitMatchBadge.classList.remove("show");
          unitMatchBadge.hidden = true;
          unitMatchBadge.style.display = "none";
          return;
        }
        const unit = normalizeText(inputUnit.value);
        const ok = Boolean(unit) && normalizeResidentUnitList(getCommunityUnits()).some((x) => x.toLowerCase() === unit.toLowerCase());
        unitMatchBadge.hidden = !ok;
        unitMatchBadge.classList.toggle("show", ok);
        unitMatchBadge.style.display = ok ? "inline-flex" : "none";
      };

      const unitPicker = modal.querySelector("#residentUnitPicker");
      const pickUnitBtn = modal.querySelector("#btnPickResidentUnit");

      const closeUnitPicker = () => {
        if (unitPicker) unitPicker.hidden = true;
        if (pickUnitBtn) pickUnitBtn.classList.remove("unlocked");
      };

      const loadUnitsForPicker = async () => {
        const rows = await resolveCommunityUnitRows([inputCommunity ? inputCommunity.value : "", activeResidentsCid]);
        if (rows.length) {
          state.currentCommunityUnits = rows;
          return rows;
        }
        return normalizeCommunityUnitRows(getCommunityUnits());
      };

      const renderUnitPicker = (rows) => {
        if (!unitPicker) return;
        unitPicker.innerHTML = "";
        let count = 0;
        (Array.isArray(rows) ? rows : []).forEach((u) => {
          const uid = String((u && u.id) || "").trim();
          if (!uid) return;
          const owner = String((u && (u.ownerName || u.owner || u.ownerText)) || "").trim();
          const btn = document.createElement("button");
          btn.type = "button";
          btn.className = "unit-option";
          const idSpan = document.createElement("span");
          idSpan.className = "unit-id";
          idSpan.textContent = uid;
          btn.appendChild(idSpan);
          if (owner) {
            const ownerSpan = document.createElement("span");
            ownerSpan.className = "unit-name";
            ownerSpan.textContent = owner;
            btn.appendChild(ownerSpan);
          }
          btn.addEventListener("click", () => {
            if (inputUnit) {
              inputUnit.value = uid;
              inputUnit.dispatchEvent(new Event("input", { bubbles: true }));
              inputUnit.focus();
            }
            closeUnitPicker();
          });
          unitPicker.appendChild(btn);
          count += 1;
        });
        if (!count) {
          const empty = document.createElement("div");
          empty.className = "unit-empty";
          empty.textContent = "尚無戶號資料";
          unitPicker.appendChild(empty);
        }
      };

      const onToggleUnitPicker = async (e) => {
        e.preventDefault();
        if (!unitPicker) return;
        if (!unitPicker.hidden) {
          closeUnitPicker();
          return;
        }
        unitPicker.innerHTML = "";
        const loading = document.createElement("div");
        loading.className = "unit-empty";
        loading.textContent = "讀取戶號中...";
        unitPicker.appendChild(loading);
        unitPicker.hidden = false;
        if (pickUnitBtn) pickUnitBtn.classList.add("unlocked");
        const rows = await loadUnitsForPicker();
        if (unitPicker.hidden) return;
        renderUnitPicker(rows);
      };
      if (pickUnitBtn) pickUnitBtn.addEventListener("click", onToggleUnitPicker);

      const onDocClickUnitPicker = (e) => {
        if (!unitPicker || unitPicker.hidden) return;
        const t = e.target;
        if (unitPicker.contains(t)) return;
        if (pickUnitBtn && pickUnitBtn.contains(t)) return;
        closeUnitPicker();
      };
      document.addEventListener("click", onDocClickUnitPicker);
      closeUnitPicker();

      const prevDetachUnitPicker = detach;
      detach = () => {
        prevDetachUnitPicker();
        document.removeEventListener("click", onDocClickUnitPicker);
        closeUnitPicker();
      };

      const fileToAvatarDataUrl = (file) => new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onerror = () => reject(new Error("read-failed"));
        reader.onload = () => {
          const img = new Image();
          img.onerror = () => reject(new Error("image-decode-failed"));
          img.onload = () => {
            const target = 360;
            const srcW = img.naturalWidth || 0;
            const srcH = img.naturalHeight || 0;
            if (!srcW || !srcH) {
              reject(new Error("bad-image"));
              return;
            }
            const side = Math.min(srcW, srcH);
            const sx = Math.round((srcW - side) / 2);
            const sy = Math.round((srcH - side) / 2);
            const canvas = document.createElement("canvas");
            canvas.width = target;
            canvas.height = target;
            const ctx = canvas.getContext("2d");
            if (!ctx) {
              reject(new Error("no-canvas"));
              return;
            }
            ctx.drawImage(img, sx, sy, side, side, 0, 0, target, target);
            resolve(canvas.toDataURL("image/jpeg", 0.78));
          };
          img.src = String(reader.result || "");
        };
        reader.readAsDataURL(file);
      });

      if (rolesWrap) {
        rolesWrap.querySelectorAll("input[type=\"checkbox\"]").forEach((el) => (el.checked = false));
      }
      if (roleOtherChk) roleOtherChk.checked = false;
      if (roleOtherText) roleOtherText.value = "";
      syncOtherRoleInput();
      if (isEdit && Array.isArray(data.residentRoles) && rolesWrap) {
        const set = new Set(data.residentRoles.map((x) => String(x || "")));
        rolesWrap.querySelectorAll("input[type=\"checkbox\"]").forEach((el) => {
          el.checked = set.has(String(el.value || ""));
        });
        const extra = normalizeText(data.residentRoleOther || "");
        if (extra && roleOtherChk) {
          roleOtherChk.checked = true;
          if (roleOtherText) roleOtherText.value = extra;
        }
        syncOtherRoleInput();
      }

      if (isEdit) {
        setAvatarPreview(String(data.avatarDataUrl || ""));
      } else {
        setAvatarPreview("");
      }

      const openPicker = () => {
        if (avatarInput) avatarInput.click();
      };

      const onUploaderClick = () => openPicker();
      const onUploaderKeydown = (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          openPicker();
        }
      };
      const onAvatarChange = () => {
        const file = avatarInput && avatarInput.files && avatarInput.files[0] ? avatarInput.files[0] : null;
        if (!file) return;
        avatarFile = file;
        const reader = new FileReader();
        reader.onload = () => setAvatarPreview(String(reader.result || ""));
        reader.readAsDataURL(file);
      };

      if (avatarUploader) avatarUploader.addEventListener("click", onUploaderClick);
      if (avatarUploader) avatarUploader.addEventListener("keydown", onUploaderKeydown);
      if (avatarInput) avatarInput.addEventListener("change", onAvatarChange);

      const onUnitInput = () => {
        unitTouched = true;
        updateUnitMatch();
        syncResidentUnitMeta({ forceBuilding: true });
      };
      if (inputUnit) inputUnit.addEventListener("input", onUnitInput);
      if (inputUnit) inputUnit.addEventListener("change", onUnitInput);
      if (inputUnit) inputUnit.addEventListener("blur", onUnitInput);
      if (inputUnit) inputUnit.addEventListener("paste", () => setTimeout(onUnitInput, 0));

      const onOtherChk = () => syncOtherRoleInput();
      if (roleOtherChk) roleOtherChk.addEventListener("change", onOtherChk);

      const onCancel = (e) => {
        e.preventDefault();
        modal.hidden = true;
        detach();
      };
      if (cancelBtn) cancelBtn.addEventListener("click", onCancel);
      if (closeBtn) closeBtn.addEventListener("click", onCancel);
      const backdrop = modal.querySelector("[data-modal-close]");
      if (backdrop) backdrop.addEventListener("click", onCancel);

      const onSubmit = async (e) => {
        e.preventDefault();
        if (submitBtn) submitBtn.disabled = true;
        setModalStatus("儲存中...", false);

        const category = normalizeText(inputCategory ? inputCategory.value : "住戶") || "住戶";
        const unit = normalizeText(inputUnit ? inputUnit.value : "");
        const subUnit = normalizeText(inputSubUnit ? inputSubUnit.value : "");
        const name = normalizeText(inputName ? inputName.value : "");
        const email = normalizeText(inputEmail ? inputEmail.value : "");
        const phone = normalizeText(inputPhone ? inputPhone.value : "");
        const passwordRaw = normalizeText(inputPassword ? inputPassword.value : "");
        const address = normalizeText(inputAddr ? inputAddr.value : "");
        const building = normalizeText(inputBuilding ? inputBuilding.value : "");
        const enabled = String(inputEnabled ? inputEnabled.value : "true") === "true";

        if (!name) {
          setModalStatus("請填寫姓名。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        if (!unit) {
          setModalStatus("請填寫戶號。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }

        // 戶號驗證：若社區已建立戶號清單，住戶戶號必須存在於清單中
        const knownUnits = normalizeResidentUnitList(getCommunityUnits());
        if (knownUnits.length && !knownUnits.some((x) => String(x || "").trim().toLowerCase() === unit.toLowerCase())) {
          setModalStatus(`戶號「${unit}」不在社區戶號清單中，請先至「戶號列表」新增，或改用清單中的戶號。`, true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }

        // 檢查子戶號重複性 (同社區、同戶號下不可重複)
        const selectedCid = normalizeText(inputCommunity ? inputCommunity.value : activeResidentsCid) || activeResidentsCid || "default";
        const isDuplicateSubUnit = getResidents().some(r => 
          r.id !== data.id && 
          String(r.community || activeResidentsCid || "default") === selectedCid &&
          r.houseNo.toLowerCase() === unit.toLowerCase() && 
          r.subUnit.toLowerCase() === subUnit.toLowerCase()
        );

        if (isDuplicateSubUnit) {
          setModalStatus(`子戶號「${subUnit || "(無)"}」在戶號「${unit}」中已存在。`, true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }

        if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          setModalStatus("電子郵件格式不正確。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        if (!phone) {
          setModalStatus("電子郵件與手機號碼皆為必填。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        const phoneNormalized = normalizePhoneDigits(phone);
        if (!phoneNormalized) {
          setModalStatus("手機號碼格式不正確。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        const password = isEdit ? passwordRaw : (passwordRaw || phone);
        if (!password && !isEdit) {
          setModalStatus("未設定預設密碼時，預設會使用手機號碼；請填寫手機號碼或預設密碼。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        const { roles, extra } = readResidentRoles();
        if (roles.includes("其他") && !extra) {
          setModalStatus("已選擇「其他」，請輸入自定義角色。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }

        let createdAuth = null;
        try {
          if (!isEdit) {
            createdAuth = await createAuthUser(email, password || phoneNormalized);
          }
          const id = isEdit ? String(data.id || "") : String(createdAuth && createdAuth.uid ? createdAuth.uid : "");
          if (!id) throw new Error("no-id");

          const selectedCid = normalizeText(inputCommunity ? inputCommunity.value : activeResidentsCid) || activeResidentsCid || "default";
          const selectedCommunity = (state.communities || []).find(c => c.id === selectedCid) || {};
          const communityCode = String(selectedCommunity.username || "");
          
          const payload = {
            role: "住戶",
            community: selectedCid,
            houseNo: unit,
            subUnit: subUnit,
            displayName: name,
            username: email,
            email,
            phone: phoneNormalized,
            phoneNormalized,
            address,
            building,
            enabled: Boolean(enabled),
            category,
            residentRoles: roles,
            residentRoleOther: extra,
            updatedAt: FieldValue.serverTimestamp(),
          };
          if (!isEdit) payload.createdAt = FieldValue.serverTimestamp();
          const passwordHash = password ? await sha256Hex(password) : "";
          if (passwordHash) {
            payload.passwordHash = passwordHash;
            payload.passwordHashAlg = "SHA-256";
            payload.passwordUpdatedAt = FieldValue.serverTimestamp();
          }
          const avatarDataUrl = avatarFile ? await fileToAvatarDataUrl(avatarFile) : "";
          if (avatarDataUrl) payload.avatarDataUrl = avatarDataUrl;
          await db.collection("users").doc(id).set(payload, { merge: true });
          await upsertUserLookup({ phoneNormalized, email, phone: phoneNormalized, uid: id, community: payload.community, communityCode, role: payload.role });

          modal.hidden = true;
          detach();
          if (typeof state.reloadResidents === "function") await state.reloadResidents();
        } catch (err) {
          console.error("Save resident error:", err);
          const code = String(err && err.code ? err.code : "");
          const msg =
            code.includes("auth/email-already-in-use") ? "此電子郵件已被使用。" :
            code.includes("auth/invalid-email") ? "電子郵件格式不正確。" :
            code.includes("auth/weak-password") ? "密碼強度不足（請確認手機號碼）。" :
            code.includes("permission-denied") ? "沒有權限執行此操作（請確認 Firestore 規則）。" :
            "儲存失敗：" + (err.message || "請稍後再試。");
          setModalStatus(msg, true);
        } finally {
          if (createdAuth && createdAuth.auth) {
            try {
              await createdAuth.auth.signOut();
            } catch {}
          }
          if (submitBtn) submitBtn.disabled = false;
        }
      };

      form.addEventListener("submit", onSubmit);
      const oldDetach = detach;
      const detach2 = () => {
        try {
          form.removeEventListener("submit", onSubmit);
        } catch {}
        try {
          if (avatarUploader) avatarUploader.removeEventListener("click", onUploaderClick);
          if (avatarUploader) avatarUploader.removeEventListener("keydown", onUploaderKeydown);
          if (avatarInput) avatarInput.removeEventListener("change", onAvatarChange);
          if (inputUnit) inputUnit.removeEventListener("input", onUnitInput);
          if (roleOtherChk) roleOtherChk.removeEventListener("change", onOtherChk);
          if (cancelBtn) cancelBtn.removeEventListener("click", onCancel);
          if (closeBtn) closeBtn.removeEventListener("click", onCancel);
          if (backdrop) backdrop.removeEventListener("click", onCancel);
        } catch {}
        oldDetach();
      };
      detach = detach2;
    };

    const openUnitsEditor = async () => {
      const modal = ensureUnitsModal();
      let detach = () => {};
      detach = bindModalClose(modal, () => detach());
      const form = modal.querySelector("#unitsForm");
      const tbody = modal.querySelector("#unitsTableBody");
      const st = modal.querySelector("#unitsStatus");
      const countEl = modal.querySelector("#unitsModalCount");
      const btnAddRow = modal.querySelector("#btnAddUnitRow");
      
      // 在函數內部獲取有效的 cid
      const currentCid = resolveActiveCommunityId();

      const setModalStatus = (msg, isError) => {
        if (!st) return;
        const t = String(msg || "").trim();
        st.textContent = t;
        st.hidden = !t;
        st.classList.toggle("error", Boolean(isError));
      };

      const createRow = (u = {}) => {
        const tr = document.createElement("tr");
        const qrToken = String(u.qrToken || u.qr || u.qrCode || "").trim();
        const ownerName = String(u.ownerName || u.owner || u.ownerText || "").trim();
        tr.innerHTML = `
          <td><input type="text" class="u-qr" value="${qrToken}" placeholder="QR code碼" /></td>
          <td><input type="text" class="u-id" value="${u.id || ""}" placeholder="戶號" /></td>
          <td><input type="text" class="u-owner" value="${ownerName}" placeholder="區分所有權人" /></td>
          <td><input type="text" class="u-address" value="${u.address || ""}" placeholder="地址" /></td>
          <td><input type="text" class="u-building" value="${u.building || u.block || ""}" placeholder="棟別" /></td>
          <td><input type="text" class="u-area" value="${u.area || ""}" placeholder="坪數" /></td>
          <td><input type="text" class="u-ownership" value="${u.ownership || ""}" placeholder="%" /></td>
          <td><div class="remove-row" title="刪除">&times;</div></td>
        `;
        tr.querySelector(".remove-row").onclick = () => {
          tr.remove();
          updateCount();
        };
        return tr;
      };

      const updateCount = () => {
        if (countEl && tbody) {
          countEl.textContent = `總戶數：${tbody.children.length}`;
        }
      };

      setModalStatus("讀取中...", false);
      modal.hidden = false;
      try {
        console.log("openUnitsEditor: 開始讀取戶號資料, currentCid:", currentCid);
        const doc = await db.collection("communities").doc(String(currentCid)).get();
        console.log("openUnitsEditor: 讀取結果 doc.exists:", doc.exists);
        const v = doc && doc.exists ? (doc.data() || {}) : {};
        console.log("openUnitsEditor: 讀取結果 v:", v);
        const units = Array.isArray(v.units) ? v.units : [];
        console.log("openUnitsEditor: 讀取結果 units:", units);
        
        // 更新頁面上的總戶數顯示
        const unitTotalEl = document.getElementById("unitTotal");
        if (unitTotalEl) {
          const normalizeUnitList = (list) => {
            const raw = Array.isArray(list) ? list : [];
            const uniq = [];
            const seen = new Set();
            for (const x of raw) {
              let val = "";
              if (typeof x === "object" && x !== null) {
                val = String(x.id || "").trim();
              } else {
                val = String(x || "").trim();
              }
              if (!val) continue;
              if (seen.has(val)) continue;
              seen.add(val);
              uniq.push(val);
            }
            return uniq;
          };
          unitTotalEl.textContent = `總戶數：${normalizeUnitList(units).length}`;
        }
        
        if (tbody) {
          tbody.innerHTML = "";
          units.forEach(u => {
            const rowData = typeof u === "object" && u !== null ? u : { id: String(u) };
            tbody.appendChild(createRow(rowData));
          });
          if (units.length === 0) tbody.appendChild(createRow());
        }
        updateCount();
        setModalStatus("", false);
      } catch (err) {
        console.error("Load units failed:", err);
        console.error("Load units failed 詳細:", JSON.stringify(err, null, 2));
        if (tbody) tbody.innerHTML = "";
        if (countEl) countEl.textContent = "總戶數：—";
        const errorMsg = "讀取失敗：" + (err.message || "請稍後再試。") + " (cid: " + String(currentCid) + ")";
        setModalStatus(errorMsg, true);
      }

      const onAddRow = () => {
        if (tbody) {
          const row = createRow();
          tbody.appendChild(row);
          updateCount();
          row.querySelector("input").focus();
        }
      };

      const onSubmit = async (e) => {
        e.preventDefault();
        if (!tbody) return;
        
        const uniq = [];
        const seen = new Set();
        const rows = Array.from(tbody.querySelectorAll("tr"));
        
        for (const tr of rows) {
          const qrToken = tr.querySelector(".u-qr").value.trim();
          const id = tr.querySelector(".u-id").value.trim();
          const ownerName = tr.querySelector(".u-owner").value.trim();
          const address = tr.querySelector(".u-address").value.trim();
          const building = tr.querySelector(".u-building").value.trim();
          const area = tr.querySelector(".u-area").value.trim();
          const ownership = tr.querySelector(".u-ownership").value.trim();
          
          if (!id) continue;
          if (seen.has(id)) continue;
          seen.add(id);

          uniq.push({ qrToken, id, ownerName, address, building, area, ownership });
        }

        if (uniq.length === 0) {
          setModalStatus("請至少輸入 1 個戶號。", true);
          return;
        }

        setModalStatus("儲存中...", false);
        try {
          await db.collection("communities").doc(String(currentCid)).set(
            { units: uniq, updatedAt: FieldValue.serverTimestamp() },
            { merge: true }
          );
          communityUnits = normalizeCommunityUnitRows(uniq);
          state.currentCommunityUnits = communityUnits;
          
          // 更新頁面上的總戶數顯示
          const unitTotalEl = document.getElementById("unitTotal");
          if (unitTotalEl) {
            const normalizeUnitList = (list) => {
              const raw = Array.isArray(list) ? list : [];
              const uniq = [];
              const seen = new Set();
              for (const x of raw) {
                let val = "";
                if (typeof x === "object" && x !== null) {
                  val = String(x.id || "").trim();
                } else {
                  val = String(x || "").trim();
                }
                if (!val) continue;
                if (seen.has(val)) continue;
                seen.add(val);
                uniq.push(val);
              }
              return uniq;
            };
            unitTotalEl.textContent = `總戶數：${normalizeUnitList(uniq).length}`;
          }
          
          modal.hidden = true;
          detach();
        } catch (err) {
          const code = String(err && err.code ? err.code : "");
          const msg = String(err && err.message ? err.message : "");
          try { console.error("Save units failed:", err); } catch {}
          if (code.includes("permission-denied")) {
            setModalStatus("沒有權限執行此操作（請更新 Firestore 規則後重整再試）。", true);
          } else if (msg) {
            setModalStatus(`儲存失敗：${msg}`, true);
          } else {
            setModalStatus("儲存失敗，請稍後再試。", true);
          }
        }
      };

      const btnExport = modal.querySelector("#btnExportUnits");
      const btnImport = modal.querySelector("#btnImportUnits");
      const inputImport = modal.querySelector("#inputImportUnits");

      const onExport = () => {
        if (!window.XLSX) {
          toast("Excel 函式庫尚未載入，請稍後再試。");
          return;
        }
        // 從目前表格抓取資料（包含尚未儲存的變更）
        const rows = Array.from(tbody.querySelectorAll("tr"));
        const data = rows.map(tr => ({
          "QR code碼": tr.querySelector(".u-qr").value.trim(),
          "戶號": tr.querySelector(".u-id").value.trim(),
          "區分所有權人": tr.querySelector(".u-owner").value.trim(),
          "地址": tr.querySelector(".u-address").value.trim(),
          "棟別": tr.querySelector(".u-building").value.trim(),
          "坪數": tr.querySelector(".u-area").value.trim(),
          "所有權人%": tr.querySelector(".u-ownership").value.trim()
        })).filter(x => x["戶號"]);

        const ws = XLSX.utils.json_to_sheet(data);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "戶號列表");
        XLSX.writeFile(wb, `戶號列表_${currentCid || "社區"}.xlsx`);
      };

      const onImportClick = () => inputImport.click();

      const onImportFile = (e) => {
        const file = e.target.files[0];
        if (!file) return;
        if (!window.XLSX) {
          toast("Excel 函式庫尚未載入，請稍後再試。");
          return;
        }
        const reader = new FileReader();
        reader.onload = (re) => {
          try {
            const data = new Uint8Array(re.target.result);
            const workbook = XLSX.read(data, { type: "array" });
            const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
            const json = XLSX.utils.sheet_to_json(firstSheet);
            
            if (json.length === 0) {
              setModalStatus("檔案中沒有資料。", true);
              return;
            }

            if (tbody) {
              tbody.innerHTML = "";
              json.forEach(row => {
                const values = Object.values(row || {});
                const qrToken = String(row["QR code碼"] || row["qrToken"] || row["qr"] || row["qrcode"] || row["QRCode"] || "").trim();
                const id = String(row["戶號"] || row["id"] || row["戶"] || Object.values(row)[0] || "").trim();
                let ownerName = String(row["區分所有權人"] || row["所有權人"] || row["ownerName"] || row["owner"] || "").trim();
                let addr = String(row["地址"] || row["address"] || "").trim();
                let building = String(row["棟別"] || row["building"] || row["block"] || "").trim();
                let area = String(row["坪數"] || row["area"] || "").trim();
                let own = String(row["所有權人%"] || row["區分所有權人%"] || row["ownership"] || "").trim();

                if (!ownerName && values.length >= 3) ownerName = String(values[2] || "").trim();
                if (!addr && values.length >= 4) addr = String(values[3] || "").trim();
                if (!building && values.length >= 7) building = String(values[4] || "").trim();
                if (!area && values.length >= 7) area = String(values[5] || "").trim();
                if (!own && values.length >= 7) own = String(values[6] || "").trim();
                if (!area && values.length >= 6) area = String(values[4] || "").trim();
                if (!own && values.length >= 6) own = String(values[5] || "").trim();

                if (id) tbody.appendChild(createRow({ qrToken, id, ownerName, address: addr, building, area, ownership: own }));
              });
              updateCount();
            }
            setModalStatus("匯入成功，請確認後點擊儲存。", false);
          } catch (err) {
            console.error("Import failed:", err);
            setModalStatus("匯入失敗，請檢查檔案格式。", true);
          } finally {
            inputImport.value = "";
          }
        };
        reader.readAsArrayBuffer(file);
      };

      if (btnAddRow) btnAddRow.addEventListener("click", onAddRow);
      if (btnExport) btnExport.addEventListener("click", onExport);
      if (btnImport) btnImport.addEventListener("click", onImportClick);
      if (inputImport) inputImport.addEventListener("change", onImportFile);

      form.addEventListener("submit", onSubmit);
      const oldDetach = detach;
      detach = () => {
        try {
          if (btnAddRow) btnAddRow.removeEventListener("click", onAddRow);
          if (btnExport) btnExport.removeEventListener("click", onExport);
          if (btnImport) btnImport.removeEventListener("click", onImportClick);
          if (inputImport) inputImport.removeEventListener("change", onImportFile);
          form.removeEventListener("submit", onSubmit);
        } catch {}
        oldDetach();
      };
    };

    renderPage();
    (async () => {
      try {
        communityUnits = await resolveCommunityUnitRows();
        state.currentCommunityUnits = communityUnits;
        refreshUnitTotals();
      } catch {}
    })();
    updateFooterActiveNav();
  }

