  function renderVisitorModule() {
    if (subnavEl) subnavEl.innerHTML = "";
    stopVisitorsSubscription();
    stopVisitorElevatorCardsSubscription();
    stopVisitorElevatorCardConfigSubscription();
    if (!Array.isArray(state.communities) || state.communities.length === 0) {
      contentEl.innerHTML = `
        <section class="card">
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg("visitor")}</div>
              <div style="min-width:0;">
                <h2>訪客登記</h2>
                <p>讀取社區資料中...</p>
              </div>
            </div>
            <a class="tag red manual-btn" data-manual="visitor" href="${manualViewerHref("visitor", "訪客登記")}" target="_blank" rel="noopener" title="開啟 訪客登記 操作手冊" aria-label="開啟 訪客登記 操作手冊">手冊</a>
          </div>
          <div class="card-bd">
            <div class="status">讀取中...</div>
          </div>
        </section>
      `.trim();
      updateFooterActiveNav();
      return;
    }

    const cid = resolveActiveCommunityId();
    const urlCommunityKey = readUrlCommunityKey();
    const activeCommunity = (Array.isArray(state.communities) ? state.communities : []).find((x) => x && String(x.id || "") === String(cid || "")) || null;
    const cname = activeCommunity ? String(activeCommunity.name || "").trim() : "";
    const creatorName = inferUserName(auth.currentUser);
    let visitorCommunitySlug = String(cid || "").trim() || "default";
    const buildVisitorCommunityCandidates = () => {
      const out = [];
      const add = (v) => {
        const s = String(v || "").trim();
        if (!s || out.includes(s)) return;
        out.push(s);
      };
      add(visitorCommunitySlug);
      add(activeCommunity ? activeCommunity.username : "");
      add(urlCommunityKey);
      try { add(sessionStorage.getItem("csp_last_cid")); } catch {}
      return out.filter((x) => x && x !== "default");
    };
    const visitorCommunityCandidates = buildVisitorCommunityCandidates();
    let visitorCommunityTryIndex = 0;
    const visitorDesc = (moduleCatalog.find((m) => m && m.id === "visitor") || {}).desc || "到訪資訊、車牌、進出時間管理";

    const today = new Date();
    const todayStr = `${today.getFullYear()}-${pad2(today.getMonth() + 1)}-${pad2(today.getDate())}`;

    if (subnavEl) {
      subnavEl.innerHTML = `
        <button class="btn btn-sm btn-primary" type="button" id="btnOverviewVisitors" data-filter="overview">
          總覽
        </button>
        <button class="btn btn-sm" type="button" id="btnPendingVisitors" data-filter="pending">
          <span class="badge-inline" id="pendingVisitorsBadge" hidden>0</span>
          待審訪客
        </button>
        <button class="btn btn-sm" type="button" id="btnApprovedVisitors" data-filter="approved">
          <span class="badge-inline" id="approvedVisitorsBadge" hidden>0</span>
          核准訪客
        </button>
        <button class="btn btn-sm" type="button" id="btnInsideVisitors" data-filter="inside">
          <span class="badge-inline" id="insideVisitorsBadge" hidden>0</span>
          入內訪客
        </button>
        <button class="btn btn-sm" type="button" id="btnHistoryVisitors" data-filter="history">
          歷史訪客
        </button>
        <button class="btn btn-sm" type="button" id="btnVisitorSettings" data-filter="settings">
          設定
        </button>
      `.trim();
      
      const filterBtns = subnavEl.querySelectorAll('[data-filter]');
      filterBtns.forEach(btn => {
        btn.onclick = () => {
          filterBtns.forEach(b => b.classList.remove('btn-primary'));
          btn.classList.add('btn-primary');
          currentFilter = btn.getAttribute('data-filter') || 'pending';
          if (currentFilter === 'history') ensureHistoryUnitNames();
          renderList();
        };
      });
    }

    contentEl.innerHTML = `
      <section class="card visitor-page">
        <div class="card-hd">
          <div class="left">
            <div class="chip" aria-hidden="true">${iconSvg("visitor")}</div>
            <div style="min-width:0;">
              <h2>訪客登記</h2>
              <p>${visitorDesc}</p>
            </div>
          </div>
        </div>
        <div class="card-bd" id="visitorPanel">
          <div class="visitor-toolbar" id="visitorToolbar">
            <div class="field">
              <label for="visitorDate">日期</label>
              <input id="visitorDate" type="date" />
            </div>
            <div class="field">
              <label for="visitorSearch">搜尋</label>
              <input id="visitorSearch" type="text" placeholder="搜尋 姓名 / 手機 / 車牌 / 事由" autocomplete="off" />
            </div>
            <button class="btn btn-sm btn-warning" type="button" id="btnVisitorQr">訪客申請連結</button>
            <button class="btn btn-sm danger" type="button" id="btnAddVisitor">新增訪客</button>
          <button class="btn btn-sm btn-success" type="button" id="btnScanVisitor" aria-label="掃描QR code" title="掃描QR code">
              掃描QR code
            </button>
          </div>
          <div class="history-toolbar" id="visitorHistoryToolbar" hidden>
            <div class="field">
              <label for="visitorHistoryUnit">戶號</label>
              <select id="visitorHistoryUnit"></select>
            </div>
            <div class="history-toolbar-actions">
              <button class="btn btn-sm" type="button" id="btnHistoryBrowse">手機版瀏覽</button>
              <button class="btn btn-sm btn-ghost" type="button" id="btnHistoryExcel">下載 Excel</button>
            </div>
          </div>
          <div class="history-toolbar" id="visitorSettingsToolbar" hidden>
            <div class="history-toolbar-actions">
              <button class="btn btn-sm btn-success" type="button" id="btnAddElevatorCard">新增電梯卡</button>
              <button class="btn btn-sm btn-ghost" type="button" id="btnOpenElevatorCardNameSettings" aria-label="設定" title="設定">
                ${iconSvg("settings")}
              </button>
            </div>
          </div>
          <div class="status" id="visitorStatus" hidden></div>
          <div class="visitor-list-container" id="visitorList">
            <div class="visitor-grid"></div>
          </div>
        </div>
      </section>
    `.trim();

    const panelEl = document.getElementById("visitorPanel");
    const listContainerEl = document.getElementById("visitorList");
    const listEl = listContainerEl.querySelector(".visitor-grid");
    const statusEl = document.getElementById("visitorStatus");
    const visitorToolbarEl = document.getElementById("visitorToolbar");
    const searchEl = document.getElementById("visitorSearch");
    const dateEl = document.getElementById("visitorDate");
    const visitorQrBtn = document.getElementById("btnVisitorQr");
    const scanBtn = document.getElementById("btnScanVisitor");
    const addBtn = document.getElementById("btnAddVisitor");
    const historyToolbarEl = document.getElementById("visitorHistoryToolbar");
    const settingsToolbarEl = document.getElementById("visitorSettingsToolbar");
    const historyUnitEl = document.getElementById("visitorHistoryUnit");
    const historyBrowseBtn = document.getElementById("btnHistoryBrowse");
    const historyExcelBtn = document.getElementById("btnHistoryExcel");
    const addElevatorCardBtn = document.getElementById("btnAddElevatorCard");
    const openElevatorCardNameSettingsBtn = document.getElementById("btnOpenElevatorCardNameSettings");

    ensureVisitorsPendingCountSubscription(cid);

    const setStatus = (msg, isError) => {
      if (!statusEl) return;
      const t = String(msg || "").trim();
      statusEl.textContent = t;
      statusEl.hidden = !t;
      statusEl.classList.toggle("error", Boolean(isError));
    };

    const toLocalInputValue = (d) => {
      if (!(d instanceof Date) || !Number.isFinite(d.getTime())) return "";
      return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}T${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
    };
    const parseLocalInputValue = (v) => {
      const raw = String(v || "").trim();
      if (!raw) return null;
      const d = new Date(raw);
      if (!Number.isFinite(d.getTime())) return null;
      return d;
    };
    const toDate = (v) => {
      if (!v) return null;
      if (v instanceof Date) return v;
      if (typeof v.toDate === "function") return v.toDate();
      return null;
    };
    const formatDt = (v) => {
      const d = toDate(v);
      if (!d) return "";
      return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`;
    };

    let visitors = [];
    let currentFilter = 'overview'; // overview, pending, approved, inside, history, settings
    let historyUnit = "";
    let historyUnitNames = new Map();
    const elevatorCardStatusMeta = (raw) => {
      const k = String(raw || "").trim().toLowerCase();
      if (k === "borrowed") return { label: "已借出", cls: "warning" };
      if (k === "disabled") return { label: "停用", cls: "" };
      return { label: "可租借", cls: "success" };
    };
    const elevatorCardOrderValue = (item) => {
      const explicit = Number(item && item.sortAtMs);
      if (Number.isFinite(explicit) && explicit > 0) return explicit;
      const updated = toDate(item && item.updatedAt);
      if (updated) return updated.getTime();
      const created = toDate(item && item.createdAt);
      if (created) return created.getTime();
      return 0;
    };
    const sortElevatorCards = (list) => {
      return [...(Array.isArray(list) ? list : [])].sort((a, b) => {
        const ao = elevatorCardOrderValue(a);
        const bo = elevatorCardOrderValue(b);
        if (ao !== bo) return ao - bo;
        const an = String(a && a.name ? a.name : "");
        const bn = String(b && b.name ? b.name : "");
        const byName = an.localeCompare(bn, "zh-Hant");
        if (byName !== 0) return byName;
        return String(a && a.code ? a.code : "").localeCompare(String(b && b.code ? b.code : ""), "zh-Hant");
      });
    };
    const renderElevatorCards = () => {
      if (!listEl) return;
      const orderedCards = sortElevatorCards(elevatorCards);
      if (!orderedCards.length) {
        listEl.innerHTML = `<div class="status">尚未建立電梯卡。</div>`;
        return;
      }
      listEl.innerHTML = `
        <div class="units-table-container" style="max-height: 560px; overflow-y: auto;">
          <table class="units-table">
            <thead>
              <tr>
                <th style="width:72px;">序號</th>
                <th>名稱</th>
                <th>編號</th>
                <th style="width:120px;">狀態</th>
                <th style="width:150px;">操作</th>
              </tr>
            </thead>
            <tbody>
              ${orderedCards.map((card, idx) => {
                const st = elevatorCardStatusMeta(card.status);
                return `
                  <tr data-card-id="${escapeHtml(String(card.id || ""))}">
                    <td>${idx + 1}</td>
                    <td>${escapeHtml(String(card.name || "—"))}</td>
                    <td>${escapeHtml(String(card.code || "—"))}</td>
                    <td><span class="status-chip ${st.cls}">${st.label}</span></td>
                    <td>
                      <div style="display:flex; gap:8px; align-items:center;">
                        <button class="btn btn-sm" type="button" data-card-edit="${escapeHtml(String(card.id || ""))}">編輯</button>
                        <button class="btn btn-sm danger" type="button" data-card-delete="${escapeHtml(String(card.id || ""))}">刪除</button>
                      </div>
                    </td>
                  </tr>
                `.trim();
              }).join("")}
            </tbody>
          </table>
        </div>
      `.trim();
    };
    const isHistoryVisitor = (v) => {
      const status = String((v && v.status) || "").toLowerCase();
      const hasOutTime = v && v.outAt != null;
      return (status === 'approved' && hasOutTime) || (status !== 'pending' && hasOutTime);
    };
    const hydrateCreatorLabels = async (list) => {
      const ids = Array.from(
        new Set(
          (Array.isArray(list) ? list : [])
            .map((x) => String(x && x.createdBy ? x.createdBy : "").trim())
            .filter(Boolean)
        )
      ).filter((x) => !state.creatorLabelByUid.has(x));
      if (!ids.length) return;
      const batchSize = 16;
      for (let i = 0; i < ids.length; i += batchSize) {
        const chunk = ids.slice(i, i + batchSize);
        await Promise.all(chunk.map((id) => getCreatorLabel80(id).catch(() => "")));
      }
      renderList();
    };

    const renderVisitorOverview = () => {
      if (!listEl) return;
      const now = new Date();
      const dayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      const dayEnd = new Date(dayStart.getTime() + 24 * 60 * 60 * 1000);
      const inToday = (v) => {
        const d = toDate(v);
        return Boolean(d) && d.getTime() >= dayStart.getTime() && d.getTime() < dayEnd.getTime();
      };
      const todays = visitors.filter((v) => inToday(v && v.createdAt) || inToday(v && v.inAt) || inToday(v && v.outAt));
      const statusOf = (v) => String((v && v.status) || "").toLowerCase();
      const partyOf = (v) => {
        const n = Number(v && v.partySize);
        return Number.isFinite(n) && n >= 1 ? Math.floor(n) : 1;
      };
      const sumParty = (list) => list.reduce((acc, v) => acc + partyOf(v), 0);

      const pendingList = todays.filter((v) => statusOf(v) === "pending");
      const approvedList = todays.filter((v) => statusOf(v) === "approved" && v.inAt == null);
      const insideList = todays.filter((v) => statusOf(v) === "approved" && v.inAt != null && v.outAt == null);
      const leftList = todays.filter((v) => v.outAt != null);
      const cards = [
        { label: "今日登記", list: todays, tone: "" },
        { label: "待審核", list: pendingList, tone: "warning" },
        { label: "已核准", list: approvedList, tone: "success" },
        { label: "入內中", list: insideList, tone: "info" },
        { label: "已離開", list: leftList, tone: "muted" },
      ];

      listEl.innerHTML = `
        <div class="visitor-overview">
          <div class="visitor-overview-head">
            <strong>今日訪客狀況</strong>
            <span>${escapeHtml(todayStr)}</span>
          </div>
          <div class="visitor-overview-grid">
            ${cards.map((c) => `
              <div class="vo-card ${c.tone ? `tone-${c.tone}` : ""}">
                <div class="vo-label">${escapeHtml(c.label)}</div>
                <div class="vo-value">${sumParty(c.list)}<span class="vo-unit">人</span></div>
                <div class="vo-sub">${c.list.length} 筆登記</div>
              </div>
            `.trim()).join("")}
          </div>
        </div>
      `.trim();
    };

    const renderList = () => {
      // 计算并更新各筛选条件的数字泡泡
      const pendingCount = visitors.filter(x => String(x.status || "").toLowerCase() === 'pending').length;
      const approvedCount = visitors.filter(x => String(x.status || "").toLowerCase() === 'approved' && !x.inAt).length;
      const insideCount = visitors.filter(x => {
        const status = String(x.status || "").toLowerCase();
        const hasInTime = x.inAt != null;
        const hasOutTime = x.outAt != null;
        return status === 'approved' && hasInTime && !hasOutTime;
      }).length;

      // 更新数字泡泡
      const pendingBadge = document.getElementById("pendingVisitorsBadge");
      if (pendingBadge) {
        pendingBadge.textContent = String(pendingCount);
        pendingBadge.hidden = pendingCount === 0;
      }
      const approvedBadge = document.getElementById("approvedVisitorsBadge");
      if (approvedBadge) {
        approvedBadge.textContent = String(approvedCount);
        approvedBadge.hidden = approvedCount === 0;
      }
      const insideBadge = document.getElementById("insideVisitorsBadge");
      if (insideBadge) {
        insideBadge.textContent = String(insideCount);
        insideBadge.hidden = insideCount === 0;
      }

      const isOverviewTab = currentFilter === 'overview';
      const isHistoryTab = currentFilter === 'history';
      const isSettingsTab = currentFilter === 'settings';
      if (historyToolbarEl) historyToolbarEl.hidden = !isHistoryTab;
      if (settingsToolbarEl) settingsToolbarEl.hidden = !isSettingsTab;
      if (visitorToolbarEl) {
        visitorToolbarEl.hidden = isSettingsTab;
        visitorToolbarEl.querySelectorAll(".field").forEach((f) => { f.hidden = isOverviewTab; });
      }
      if (isOverviewTab) {
        renderVisitorOverview();
        return;
      }
      if (isHistoryTab) refreshHistoryUnitOptions();
      if (isSettingsTab) {
        renderElevatorCards();
        return;
      }

      const q = String(searchEl ? searchEl.value : "").trim().toLowerCase();
      const dateVal = String(dateEl ? dateEl.value : "").trim();
      
      let filtered = visitors;
      
      // 根据筛选按钮过滤
      if (currentFilter === 'pending') {
        filtered = filtered.filter(x => String(x.status || "").toLowerCase() === 'pending');
      } else if (currentFilter === 'approved') {
        filtered = filtered.filter(x => String(x.status || "").toLowerCase() === 'approved' && !x.inAt);
      } else if (currentFilter === 'inside') {
        filtered = filtered.filter(x => {
          const status = String(x.status || "").toLowerCase();
          const hasInTime = x.inAt != null;
          const hasOutTime = x.outAt != null;
          return status === 'approved' && hasInTime && !hasOutTime;
        });
      } else if (currentFilter === 'history') {
        filtered = filtered.filter(isHistoryVisitor);
        if (historyUnit) filtered = filtered.filter((x) => String(x.unit || "").trim() === historyUnit);
      }
      
      // 日期筛选
      if (dateVal) {
        filtered = filtered.filter((x) => {
          const vDate = toDate(x.inAt) || toDate(x.createdAt);
          if (!vDate) return false;
          const vDateStr = `${vDate.getFullYear()}-${pad2(vDate.getMonth()+1)}-${pad2(vDate.getDate())}`;
          return vDateStr === dateVal;
        });
      }
      
      // 关键词筛选
      if (q) {
        filtered = filtered.filter((x) => {
          const n = String(x.name || "").toLowerCase();
          const p = String(x.phone || "").toLowerCase();
          const em = String(x.email || "").toLowerCase();
          const unit = String(x.unit || "").toLowerCase();
          const plate = String(x.plate || "").toLowerCase();
          const purpose = String(x.purpose || "").toLowerCase();
          return n.includes(q) || p.includes(q) || em.includes(q) || unit.includes(q) || plate.includes(q) || purpose.includes(q);
        });
      }

      if (!listEl) return;
      if (!filtered.length) {
        const emptyText = 
          currentFilter === 'pending' ? '尚無待審訪客。' :
          currentFilter === 'approved' ? '尚無核准訪客。' :
          currentFilter === 'inside' ? '尚無入內訪客。' :
          '尚無歷史訪客。';
        listEl.innerHTML = `<div class="status">${emptyText}</div>`;
        return;
      }

      const sortTime = (v) => (toDate(v && v.inAt) || toDate(v && v.createdAt) || new Date(0)).getTime();
      const ordered = [...filtered].sort((a, b) => {
        return sortTime(b) - sortTime(a);
      });

      listEl.innerHTML = ordered
        .map((v) => {
          const name = String(v.name || "—");
          const unit = String(v.unit || "").trim();
          const phone = String(v.phone || "").trim();
          const plate = String(v.plate || "").trim();
          const purpose = String(v.purpose || "").trim();
          const email = String(v.email || "").trim();
          const party = v.partySize != null && Number.isFinite(Number(v.partySize)) && Number(v.partySize) >= 1 ? String(Math.floor(Number(v.partySize))) : "1";
          const keepText = formatKeepText80(v.keep, v.outAt);
          const plateText = plate || "—";
          const inText = formatDt(v.inAt);
          const outText = formatDt(v.outAt);
          const createdText = formatDt(v.createdAt);
          const createdByUid = String(v.createdBy || "").trim();
          const createdByName =
            createdByUid && state.creatorLabelByUid.has(createdByUid)
              ? String(state.creatorLabelByUid.get(createdByUid) || "").trim()
              : String(v.createdByName || "").trim();
          const subHtml = [
            `<span class="field-k">拜訪戶號：</span>${escapeHtml(unit || "—")}`,
            `<span class="field-k">手機：</span>${escapeHtml(phone || "—")}`,
            `<span class="field-k">到訪事由：</span>${escapeHtml(purpose || "—")}`,
          ].join("｜");
          const sub2Html = [
            `<span class="field-k">拜訪人數：</span>${escapeHtml(party)}`,
            `<span class="field-k">電子郵件：</span>${escapeHtml(email || "—")}`,
          ].join("｜");
          const status = String(v.status || "").toLowerCase();
          const isPending = status === "pending";
          const isApproved = status === "approved";
          return `
            <div class="visitor-item ${isPending ? "pending" : ""} ${isApproved ? "approved" : ""}" data-id="${String(v.id || "")}">
              <div class="visitor-left">
                <div class="visitor-text">
                  <div class="visitor-top-row">
                    <div class="visitor-name">${name}</div>
                    <div class="visitor-created"><span class="field-k">建立：</span>${escapeHtml(createdText || "—")}｜<span class="field-k">建立者：</span>${escapeHtml(createdByName || "—")}</div>
                  </div>
                  <div class="visitor-sub-row">
                    <div class="visitor-sub">${subHtml}</div>
                    <div class="visitor-sub2">${sub2Html}</div>
                    <div class="visitor-keep"><span class="field-k">車牌：</span>${escapeHtml(plateText)}｜<span class="field-k">留存：</span>${escapeHtml(keepText || "無")}</div>
                  </div>
                  ${isApproved ? `
                    <div class="visitor-meta">
                      <span class="time-pill in" role="button" tabindex="0" data-time-kind="in">來訪：${inText || "—"}</span>
                      <span class="time-pill out" role="button" tabindex="0" data-time-kind="out">離開：${outText || "—"}</span>
                    </div>
                  ` : ""}
                </div>
              </div>
              <div class="visitor-actions">
                <button class="icon-btn ${isPending ? "warning" : ""}" type="button" data-pass aria-label="${isPending ? "待審核" : "訪客證"}" title="${isPending ? "待審核" : "訪客證"}">
                  ${isPending ? `
                    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                      <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                      <path d="M12 8v4l3 2" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>
                    </svg>
                  ` : `
                    <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                      <path d="M6.5 4.8h11A2.2 2.2 0 0 1 19.7 7v10A2.2 2.2 0 0 1 17.5 19.2h-11A2.2 2.2 0 0 1 4.3 17V7A2.2 2.2 0 0 1 6.5 4.8Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                      <path d="M8 9.2h2.2M13.8 9.2H16" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                      <path d="M8 12h8" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                      <path d="M8 14.8h5.4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                      <path d="M15.4 14.2a1.4 1.4 0 1 0 2.8 0 1.4 1.4 0 0 0-2.8 0Z" stroke="currentColor" stroke-width="1.7"/>
                    </svg>
                  `}
                </button>
                <button class="icon-btn" type="button" data-edit aria-label="編輯" title="編輯">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M4 20h4l10.5-10.5a2 2 0 0 0 0-2.8l-.2-.2a2 2 0 0 0-2.8 0L5 17v3Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M13.5 6.5 17.5 10.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                  </svg>
                </button>
                <button class="icon-btn danger" type="button" data-delete aria-label="刪除" title="刪除">
                  <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                    <path d="M9 4h6l1 2h4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                    <path d="M6 6h12l-1 14a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L6 6Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
                    <path d="M10 11v6M14 11v6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>
                  </svg>
                </button>
              </div>
            </div>
          `.trim();
        })
        .join("");
    };

    const docIdForHistoryUnit = (unit) => {
      let s = String(unit || "").trim().replace(/\//g, "_");
      if (!s || s === "." || s === "..") s = `_${s}`;
      return s;
    };

    const historyStatusLabel = (raw) => {
      const k = String(raw || "").toLowerCase();
      if (k === "approved") return "已核准";
      if (k === "pending") return "待審核";
      if (k === "cancelled" || k === "canceled") return "已取消";
      if (k === "rejected") return "已拒絕";
      return String(raw || "") || "—";
    };

    const formatMs = (ms) => {
      if (ms == null || !Number.isFinite(Number(ms))) return "";
      const d = new Date(Number(ms));
      if (!Number.isFinite(d.getTime())) return "";
      return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`;
    };

    const currentMonthKey = (d) => {
      const dt = d instanceof Date ? d : new Date();
      return `${dt.getFullYear()}-${pad2(dt.getMonth() + 1)}`;
    };

    const buildHistoryRecords = (unit) => {
      const u = String(unit || "").trim();
      return (Array.isArray(visitors) ? visitors : [])
        .filter((v) => String(v.unit || "").trim() === u && isHistoryVisitor(v))
        .map((v) => {
          const inDate = toDate(v.inAt);
          const outDate = toDate(v.outAt);
          const createdDate = toDate(v.createdAt);
          return {
            id: String(v.id || ""),
            name: String(v.name || ""),
            phone: String(v.phone || ""),
            plate: String(v.plate || ""),
            purpose: String(v.purpose || ""),
            partySize: v.partySize != null && Number.isFinite(Number(v.partySize)) && Number(v.partySize) >= 1 ? Math.floor(Number(v.partySize)) : 1,
            status: String(v.status || ""),
            inAt: inDate ? inDate.getTime() : null,
            outAt: outDate ? outDate.getTime() : null,
            createdAt: createdDate ? createdDate.getTime() : null,
          };
        })
        .sort((a, b) => (b.inAt || b.createdAt || 0) - (a.inAt || a.createdAt || 0));
    };

    const listHistoryUnits = () => Array.from(new Set(
      (Array.isArray(visitors) ? visitors : [])
        .filter(isHistoryVisitor)
        .map((v) => String(v.unit || "").trim())
        .filter(Boolean)
    )).sort((a, b) => String(a).localeCompare(String(b), "zh-Hant"));

    const refreshHistoryUnitOptions = () => {
      if (!historyUnitEl) return;
      const unitSet = new Set(listHistoryUnits());
      (Array.isArray(residentOptions) ? residentOptions : []).forEach((r) => {
        const id = String(r && r.id ? r.id : "").trim();
        if (id) unitSet.add(id);
      });
      const units = Array.from(unitSet).sort((a, b) => String(a).localeCompare(String(b), "zh-Hant"));
      const prev = String(historyUnitEl.value || historyUnit || "");
      historyUnitEl.innerHTML = "";
      const allOpt = document.createElement("option");
      allOpt.value = "";
      allOpt.textContent = units.length ? "全部戶號" : "尚無戶號";
      historyUnitEl.appendChild(allOpt);
      units.forEach((u) => {
        const opt = document.createElement("option");
        opt.value = u;
        const nm = String(historyUnitNames.get(u) || "");
        opt.textContent = nm ? `${u}（${nm}）` : u;
        historyUnitEl.appendChild(opt);
      });
      historyUnitEl.value = units.includes(prev) ? prev : "";
      historyUnit = String(historyUnitEl.value || "");
    };

    let historyNamesLoaded = false;
    const ensureHistoryUnitNames = async () => {
      if (historyNamesLoaded) return;
      historyNamesLoaded = true;
      try {
        if (!residentOptions.length) residentOptions = await loadResidentOptions();
        historyUnitNames = new Map(
          (Array.isArray(residentOptions) ? residentOptions : [])
            .map((u) => [String(u.id || "").trim(), String(u.name || "").trim()])
            .filter(([id]) => Boolean(id))
        );
        refreshHistoryUnitOptions();
        renderList();
      } catch {
        historyNamesLoaded = false;
      }
    };

    const publishUnitHistory = async (unit) => {
      const u = String(unit || "").trim();
      if (!u) return false;
      const records = buildHistoryRecords(u);
      const docRef = db
        .collection("communities")
        .doc(String(visitorCommunitySlug || "default"))
        .collection("visitor_history")
        .doc(docIdForHistoryUnit(u));
      await docRef.set({
        unit: u,
        name: String(historyUnitNames.get(u) || ""),
        count: records.length,
        updatedAt: new Date(),
        records,
      }, { merge: false });
      return true;
    };

    const historySheetName = (unit, used) => {
      let base = String(unit || "戶號").replace(/[\[\]\*\/\\\?:]/g, "_").trim() || "戶號";
      if (base.length > 28) base = base.slice(0, 28);
      let name = base;
      let i = 2;
      while (used.has(name)) {
        name = `${base.slice(0, 26)}_${i}`;
        i += 1;
      }
      used.add(name);
      return name;
    };

    const exportHistoryExcel = () => {
      if (!window.XLSX) {
        toast("Excel 函式庫尚未載入，請稍後再試。");
        return;
      }
      const unitSet = new Set(listHistoryUnits());
      (Array.isArray(residentOptions) ? residentOptions : []).forEach((r) => {
        const id = String(r && r.id ? r.id : "").trim();
        if (id) unitSet.add(id);
      });
      const units = Array.from(unitSet).sort((a, b) => String(a).localeCompare(String(b), "zh-Hant"));
      if (!units.length) {
        toast("尚無戶號資料。");
        return;
      }
      const wb = XLSX.utils.book_new();
      const used = new Set();
      units.forEach((u) => {
        const rows = buildHistoryRecords(u).map((r) => ({
          "訪客姓名": r.name,
          "手機": r.phone,
          "車牌": r.plate,
          "到訪事由": r.purpose,
          "拜訪人數": r.partySize,
          "狀態": historyStatusLabel(r.status),
          "來訪時間": formatMs(r.inAt),
          "離開時間": formatMs(r.outAt),
          "建立時間": formatMs(r.createdAt),
        }));
        const ws = rows.length
          ? XLSX.utils.json_to_sheet(rows)
          : XLSX.utils.aoa_to_sheet([["尚無紀錄"]]);
        XLSX.utils.book_append_sheet(wb, ws, historySheetName(u, used));
      });
      XLSX.writeFile(wb, `歷史訪客_${cname || visitorCommunitySlug || "社區"}_${currentMonthKey().replace("-", "")}.xlsx`);
    };

    const applyLocalVisitorPatch = (id, patch) => {
      const idx = visitors.findIndex((x) => String(x.id || "") === String(id || ""));
      if (idx < 0) return;
      const cur = visitors[idx] || {};
      visitors[idx] = { ...cur, ...patch };
      visitors.sort((a, b) => {
        const at = (toDate(a.inAt) || toDate(a.createdAt) || new Date(0)).getTime();
        const bt = (toDate(b.inAt) || toDate(b.createdAt) || new Date(0)).getTime();
        return bt - at;
      });
      renderList();
    };

    const openTimeEditorFromPill = (pillEl) => {
      if (!pillEl) return;
      const itemEl = pillEl.closest ? pillEl.closest(".visitor-item[data-id]") : null;
      const vid = itemEl ? String(itemEl.getAttribute("data-id") || "").trim() : "";
      if (!vid) return;
      const kind = String(pillEl.getAttribute("data-time-kind") || "").trim() === "out" ? "out" : "in";
      const v = visitors.find((x) => String(x.id || "") === vid) || null;
      const initialDate = v ? (kind === "out" ? toDate(v.outAt) : toDate(v.inAt)) : null;
      openVisitorTimeModal80({ cid: visitorCommunitySlug, visitorId: vid, kind, initialDate, onApplied: applyLocalVisitorPatch });
    };

    const collRef = () => db.collection("communities").doc(String(visitorCommunitySlug || "default")).collection("visitors");
    const elevatorCardCollRef = () => db.collection("communities").doc(String(visitorCommunitySlug || "default")).collection("visitor_elevator_cards");
    const elevatorCardConfigRef = () => db.collection("communities").doc(String(visitorCommunitySlug || "default")).collection("settings").doc("visitor_elevator_card_config");
    const subscribeElevatorCards = () => {
      stopVisitorElevatorCardsSubscription();
      try {
        state.unsubVisitorElevatorCards = elevatorCardCollRef().onSnapshot((snap) => {
          elevatorCards = (snap && snap.docs ? snap.docs : []).map((d) => {
            const v = d.data() || {};
            return {
              id: d.id,
              name: String(v.name || ""),
              code: String(v.code || ""),
              status: String(v.status || "available"),
              sortAtMs: Number(v.sortAtMs || 0) || 0,
              createdAt: v.createdAt || null,
              updatedAt: v.updatedAt || null,
            };
          });
          renderList();
        }, () => {
          elevatorCards = [];
          renderList();
        });
      } catch {
        elevatorCards = [];
      }
    };
    const subscribeElevatorCardConfig = () => {
      stopVisitorElevatorCardConfigSubscription();
      try {
        state.unsubVisitorElevatorCardConfig = elevatorCardConfigRef().onSnapshot((snap) => {
          const v = snap && snap.exists ? (snap.data() || {}) : {};
          elevatorCardNameOptions = normalizeOptionTextList(v.cardNameOptions);
          visitorKeepCertTypeOptions = normalizeOptionTextList(v.certTypeOptions);
          const liveSelect = document.getElementById("visitorElevatorCardName");
          if (liveSelect && String(liveSelect.tagName || "").toUpperCase() === "SELECT") {
            const currentValue = String(liveSelect.value || liveSelect.getAttribute("data-current-value") || "");
            renderElevatorCardNameSelect(liveSelect, currentValue);
          }
          const keepCertSelect = document.getElementById("modal_v_keep_cert_type");
          if (keepCertSelect && String(keepCertSelect.tagName || "").toUpperCase() === "SELECT") {
            renderVisitorKeepCertTypeSelect(keepCertSelect, String(keepCertSelect.value || keepCertSelect.getAttribute("data-current-value") || ""));
          }
          const scanKeepCertSelect = document.getElementById("visitorScanKeepCertType");
          if (scanKeepCertSelect && String(scanKeepCertSelect.tagName || "").toUpperCase() === "SELECT") {
            renderVisitorKeepCertTypeSelect(scanKeepCertSelect, String(scanKeepCertSelect.value || scanKeepCertSelect.getAttribute("data-current-value") || ""));
          }
        }, () => {
          elevatorCardNameOptions = [];
          visitorKeepCertTypeOptions = [];
        });
      } catch {
        elevatorCardNameOptions = [];
        visitorKeepCertTypeOptions = [];
      }
    };

    const subscribeVisitors = () => {
      setStatus("讀取中...", false);

      try {
        const startAt = (slug) => {
          stopVisitorsSubscription();
          visitorCommunitySlug = String(slug || "").trim() || visitorCommunitySlug || "default";
          subscribeElevatorCards();
          subscribeElevatorCardConfig();
          state.unsubVisitors = collRef()
            .orderBy("createdAt", "desc")
            .onSnapshot(
            (snap) => {
              const list = (snap && snap.docs ? snap.docs : []).map((d) => {
                const v = d.data() || {};
                const rawStatus = String(v.status || "").trim().toLowerCase();
                const passAuthorized = Boolean(v.passAuthorized);
                const status = rawStatus || (passAuthorized ? "approved" : "");
                return {
                  id: d.id,
                  qrToken: String(v.qrToken || ""),
                  name: String(v.name || v.visitorName || ""),
                  email: String(v.email || ""),
                  phone: String(v.phone || ""),
                  unit: String(v.unit || v.visitUnit || ""),
                  plate: String(v.plate || v.carPlate || ""),
                  purpose: String(v.purpose || ""),
                  purposeType: String(v.purposeType || ""),
                  purposeOther: String(v.purposeOther || ""),
                  note: String(v.note || ""),
                  inAt: v.inAt || v.inTime || null,
                  outAt: v.outAt || v.outTime || null,
                  partySize: v.partySize != null ? Number(v.partySize) : null,
                  qrInvalidated: Boolean(v.qrInvalidated),
                  keep: v.keep || null,
                  createdBy: String(v.createdBy || ""),
                  createdByName: String(v.createdByName || ""),
                  createdAt: v.createdAt || null,
                  updatedAt: v.updatedAt || null,
                  status,
                  passAuthorized,
                };
              });
              visitors = list;
              setStatus("", false);
              renderList();
              hydrateCreatorLabels(list).catch(() => {});
            },
            (err) => {
              const code = String(err && err.code ? err.code : "");
              if (code.includes("permission-denied") && visitorCommunityTryIndex + 1 < visitorCommunityCandidates.length) {
                visitorCommunityTryIndex += 1;
                setStatus("讀取中...", false);
                startAt(visitorCommunityCandidates[visitorCommunityTryIndex]);
                return;
              }
              setStatus(code.includes("permission-denied") ? "沒有權限讀取訪客資料。" : "讀取失敗，請稍後再試。", true);
              visitors = [];
              renderList();
            }
            );
        };
        const first = visitorCommunityCandidates[0] || String(cid || "default");
        startAt(first);
      } catch {
        setStatus("讀取失敗，請稍後再試。", true);
      }
    };

    let residentOptions = [];
    const loadResidentOptions = async () => {
      const candidates = [];
      const add = (v) => {
        const s = String(v || "").trim();
        if (!s || candidates.includes(s)) return;
        candidates.push(s);
      };
      add(visitorCommunitySlug);
      add(cid);
      add(activeCommunity ? activeCommunity.username : "");
      add(urlCommunityKey);
      try { add(sessionStorage.getItem("csp_last_cid")); } catch {}

      for (const slug of candidates) {
        // 戶號來源以 communities/{slug}.units 為準（公開可讀，社區帳號亦可讀取）
        let unitRows = [];
        try {
          const doc = await db.collection("communities").doc(String(slug)).get();
          if (doc && doc.exists) {
            const v = doc.data() || {};
            unitRows = normalizeCommunityUnitRows(v.units);
          }
        } catch {}
        if (!unitRows.length) continue;

        const nameByUnit = new Map();
        unitRows.forEach((u) => {
          const uid = String(u.id || "").trim();
          if (!uid) return;
          const nm = String(u.ownerName || u.owner || u.name || "").trim();
          if (nm) nameByUnit.set(uid, nm);
        });

        // 以住戶名單補齊姓名（權限不足時忽略）
        try {
          const [snapA, snapB] = await Promise.all([
            db.collection("users").where("community", "==", String(slug)).get(),
            db.collection("users").where("communityIds", "array-contains", String(slug)).get(),
          ]);
          const merged = new Map();
          [...(snapA && snapA.docs ? snapA.docs : []), ...(snapB && snapB.docs ? snapB.docs : [])].forEach((d) => {
            if (d && d.id) merged.set(String(d.id), d);
          });
          merged.forEach((d) => {
            const v = (d && typeof d.data === "function") ? (d.data() || {}) : {};
            const houseNo = String(v.houseNo || v.unit || "").trim();
            const subUnit = String(v.subUnit || "").trim();
            const uid = [houseNo, subUnit].filter(Boolean).join("-");
            if (!uid || nameByUnit.get(uid)) return;
            if (!isResidentRole(String(v.role || "")) || String(v.status || "") === "pending") return;
            const nm = String(v.displayName || v.name || "").trim();
            if (nm) nameByUnit.set(uid, nm);
          });
        } catch {}

        const rows = unitRows
          .map((u) => String(u.id || "").trim())
          .filter(Boolean)
          .map((uid) => ({
            id: uid,
            name: String(nameByUnit.get(uid) || "").trim(),
            role: "resident",
            status: "",
          }));
        if (rows.length) {
          rows.sort((a, b) => String(a.id).localeCompare(String(b.id), "zh-Hant"));
          return rows;
        }
      }
      return [];
    };

    const ensureVisitorElevatorCardModal = () => {
      let modal = document.getElementById("visitorElevatorCardModal");
      if (modal) return modal;
      modal = document.createElement("div");
      modal.className = "modal";
      modal.id = "visitorElevatorCardModal";
      modal.hidden = true;
      modal.innerHTML = `
        <div class="modal-backdrop" data-modal-close="1"></div>
        <div class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="visitorElevatorCardModalTitle">
          <div class="modal-hd">
            <h3 class="modal-title" id="visitorElevatorCardModalTitle">新增電梯卡</h3>
            <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
          </div>
          <form id="visitorElevatorCardForm">
            <div class="modal-body">
              <div class="field">
                <label for="visitorElevatorCardName">名稱</label>
                <select id="visitorElevatorCardName"></select>
              </div>
              <div class="field">
                <label for="visitorElevatorCardCode">編號</label>
                <input id="visitorElevatorCardCode" type="text" autocomplete="off" />
              </div>
              <div class="field">
                <label for="visitorElevatorCardStatus">狀態</label>
                <select id="visitorElevatorCardStatus">
                  <option value="available">可租借</option>
                  <option value="borrowed">已借出</option>
                  <option value="disabled">停用</option>
                </select>
              </div>
              <div class="status" id="visitorElevatorCardStatusBox" hidden></div>
            </div>
            <div class="modal-ft">
              <button class="btn" type="button" id="btnCloseVisitorElevatorCardModal">取消</button>
              <button class="btn btn-primary" type="submit" id="btnSubmitVisitorElevatorCardModal">儲存</button>
            </div>
          </form>
        </div>
      `.trim();
      document.body.appendChild(modal);
      return modal;
    };

    const ensureVisitorElevatorCardNameSettingsModal = () => {
      let modal = document.getElementById("visitorElevatorCardNameSettingsModal");
      if (modal) return modal;
      modal = document.createElement("div");
      modal.className = "modal";
      modal.id = "visitorElevatorCardNameSettingsModal";
      modal.hidden = true;
      modal.innerHTML = `
        <div class="modal-backdrop" data-modal-close="1"></div>
          <div class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="visitorElevatorCardNameSettingsTitle">
          <div class="modal-hd">
              <h3 class="modal-title" id="visitorElevatorCardNameSettingsTitle">電梯卡與證件類別設定</h3>
            <button class="modal-close" type="button" data-modal-close="1" aria-label="關閉">×</button>
          </div>
          <div class="modal-body">
            <div class="field">
              <label for="visitorElevatorCardOptionKind">新增 / 編輯選項</label>
              <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
                <select id="visitorElevatorCardOptionKind" style="flex:0 0 160px;">
                  <option value="card">電梯卡名稱</option>
                  <option value="cert">質押證件類別</option>
                </select>
                <input id="visitorElevatorCardOptionInput" type="text" autocomplete="off" style="flex:1 1 220px;" />
                <button class="btn btn-sm btn-success" type="button" id="btnSaveVisitorElevatorCardOption">新增</button>
              </div>
              <div class="muted" style="margin-top:6px;">可切換維護「電梯卡名稱」與「質押證件類別」兩種選項。</div>
            </div>
            <div class="status" id="visitorElevatorCardOptionStatus" hidden></div>
            <div class="units-table-container" style="max-height: 420px; overflow-y: auto;">
              <table class="units-table">
                <thead>
                  <tr>
                    <th style="width:72px;">序號</th>
                    <th style="width:140px;">類型</th>
                    <th>名稱</th>
                    <th style="width:150px;">操作</th>
                  </tr>
                </thead>
                <tbody id="visitorElevatorCardOptionRows"></tbody>
              </table>
            </div>
          </div>
          <div class="modal-ft">
            <button class="btn" type="button" id="btnCloseVisitorElevatorCardNameSettingsModal">關閉</button>
          </div>
        </div>
      `.trim();
      document.body.appendChild(modal);
      return modal;
    };

    const openElevatorCardNameSettings = () => {
      const modal = ensureVisitorElevatorCardNameSettingsModal();
      let detach = () => {};
      const detachModalClose = bindModalClose(modal, () => detach());
      const kindEl = modal.querySelector("#visitorElevatorCardOptionKind");
      const inputEl = modal.querySelector("#visitorElevatorCardOptionInput");
      const saveBtn = modal.querySelector("#btnSaveVisitorElevatorCardOption");
      const closeBtn = modal.querySelector("#btnCloseVisitorElevatorCardNameSettingsModal");
      const rowsEl = modal.querySelector("#visitorElevatorCardOptionRows");
      const statusEl = modal.querySelector("#visitorElevatorCardOptionStatus");
      let draftCardNames = normalizeOptionTextList(elevatorCardNameOptions);
      let draftCertTypes = normalizeOptionTextList(visitorKeepCertTypeOptions.length ? visitorKeepCertTypeOptions : ["身分證", "健保卡", "駕照"]);
      let editingType = "card";
      let editingIndex = -1;

      const setStatus = (msg, isError) => {
        if (!statusEl) return;
        const t = String(msg || "").trim();
        statusEl.textContent = t;
        statusEl.hidden = !t;
        statusEl.classList.toggle("error", Boolean(isError));
      };
      const getOptionKind = () => (kindEl && String(kindEl.value || "") === "cert" ? "cert" : "card");
      const syncEditorUi = () => {
        if (kindEl) kindEl.value = editingType === "cert" ? "cert" : "card";
        if (inputEl) inputEl.placeholder = editingType === "cert" ? "請輸入證件類別" : "請輸入電梯卡名稱";
        if (saveBtn) {
          if (editingIndex >= 0) saveBtn.textContent = editingType === "cert" ? "更新證件類別" : "更新名稱";
          else saveBtn.textContent = editingType === "cert" ? "新增證件類別" : "新增名稱";
        }
      };
      const resetEditor = () => {
        editingIndex = -1;
        editingType = getOptionKind();
        if (inputEl) inputEl.value = "";
        syncEditorUi();
        setStatus("", false);
      };
      const getDraftList = (type) => type === "cert" ? draftCertTypes : draftCardNames;
      const renderRows = () => {
        if (!rowsEl) return;
        const cardRows = draftCardNames.map((name, idx) => `
          <tr data-option-index="${idx}" data-option-kind="card">
            <td>${idx + 1}</td>
            <td>電梯卡名稱</td>
            <td>${escapeHtml(name)}</td>
            <td>
              <div style="display:flex; gap:8px; align-items:center;">
                <button class="btn btn-sm" type="button" data-option-edit="card:${idx}">編輯</button>
                <button class="btn btn-sm danger" type="button" data-option-delete="card:${idx}">刪除</button>
              </div>
            </td>
          </tr>
        `);
        const certRows = draftCertTypes.map((name, idx) => `
          <tr data-option-index="${idx}" data-option-kind="cert">
            <td>${idx + 1}</td>
            <td>質押證件類別</td>
            <td>${escapeHtml(name)}</td>
            <td>
              <div style="display:flex; gap:8px; align-items:center;">
                <button class="btn btn-sm" type="button" data-option-edit="cert:${idx}">編輯</button>
                <button class="btn btn-sm danger" type="button" data-option-delete="cert:${idx}">刪除</button>
              </div>
            </td>
          </tr>
        `);
        const allRows = cardRows.concat(certRows);
        if (!allRows.length) {
          rowsEl.innerHTML = '<tr><td colspan="4"><div class="status">尚未建立選項。</div></td></tr>';
          return;
        }
        rowsEl.innerHTML = allRows.join("");
      };
      const persistOptions = async (nextCardList, nextCertList, successText) => {
        const normalizedCards = normalizeOptionTextList(nextCardList);
        const normalizedCerts = normalizeOptionTextList(nextCertList);
        if (saveBtn) saveBtn.disabled = true;
        setStatus("儲存中...", false);
        try {
          await elevatorCardConfigRef().set({
            cardNameOptions: normalizedCards,
            certTypeOptions: normalizedCerts,
            updatedAt: FieldValue.serverTimestamp(),
          }, { merge: true });
          elevatorCardNameOptions = normalizedCards;
          visitorKeepCertTypeOptions = normalizedCerts;
          draftCardNames = normalizedCards.slice();
          draftCertTypes = normalizedCerts.slice();
          renderRows();
          resetEditor();
          toast(successText);
        } catch (err) {
          const codeText = String(err && err.code ? err.code : "");
          setStatus(codeText.includes("permission-denied") ? "沒有權限執行此操作。" : "儲存失敗，請稍後再試。", true);
        } finally {
          if (saveBtn) saveBtn.disabled = false;
        }
      };
      const onSave = async () => {
        const value = normalizeText(inputEl ? inputEl.value : "");
        if (!value) {
          setStatus("請輸入名稱。", true);
          return;
        }
        const targetType = editingIndex >= 0 ? editingType : getOptionKind();
        const activeList = getDraftList(targetType);
        const duplicateIndex = activeList.findIndex((x, idx) => x === value && idx !== editingIndex);
        if (duplicateIndex >= 0) {
          setStatus("名稱不可重複。", true);
          return;
        }
        const nextCardList = draftCardNames.slice();
        const nextCertList = draftCertTypes.slice();
        const targetList = targetType === "cert" ? nextCertList : nextCardList;
        if (editingIndex >= 0) targetList[editingIndex] = value;
        else targetList.push(value);
        await persistOptions(nextCardList, nextCertList, editingIndex >= 0 ? "已更新設定選項" : "已新增設定選項");
      };
      const onKindChange = () => {
        editingType = getOptionKind();
        if (editingIndex >= 0) {
          editingIndex = -1;
          if (inputEl) inputEl.value = "";
        }
        syncEditorUi();
        setStatus("", false);
        if (inputEl) inputEl.focus();
      };
      const onRowsClick = async (e) => {
        const editBtn = e.target && e.target.closest ? e.target.closest("[data-option-edit]") : null;
        if (editBtn) {
          const token = String(editBtn.getAttribute("data-option-edit") || "");
          const parts = token.split(":");
          const type = parts[0] === "cert" ? "cert" : "card";
          const idx = Number(parts[1]);
          const activeList = getDraftList(type);
          if (!Number.isInteger(idx) || idx < 0 || idx >= activeList.length) return;
          editingType = type;
          editingIndex = idx;
          if (inputEl) inputEl.value = String(activeList[idx] || "");
          syncEditorUi();
          setStatus("", false);
          if (inputEl) inputEl.focus();
          return;
        }
        const delBtn = e.target && e.target.closest ? e.target.closest("[data-option-delete]") : null;
        if (!delBtn) return;
        const token = String(delBtn.getAttribute("data-option-delete") || "");
        const parts = token.split(":");
        const type = parts[0] === "cert" ? "cert" : "card";
        const idx = Number(parts[1]);
        const activeList = getDraftList(type);
        if (!Number.isInteger(idx) || idx < 0 || idx >= activeList.length) return;
        const targetName = String(activeList[idx] || "");
        const ok = await (window.nwConfirm ? window.nwConfirm({
          title: "確認刪除",
          message: `確定要刪除選項「${targetName}」？`,
          okText: "刪除",
          cancelText: "取消",
          danger: true,
        }) : Promise.resolve(window.confirm("確定要刪除？")));
        if (!ok) return;
        const nextCardList = draftCardNames.slice();
        const nextCertList = draftCertTypes.slice();
        const targetList = type === "cert" ? nextCertList : nextCardList;
        targetList.splice(idx, 1);
        await persistOptions(nextCardList, nextCertList, "已刪除設定選項");
      };
      const onInputKeydown = (e) => {
        if (e.key !== "Enter") return;
        e.preventDefault();
        onSave().catch(() => {});
      };
      const onSaveClick = (e) => {
        e.preventDefault();
        onSave().catch(() => {});
      };
      const onClose = (e) => {
        if (e) e.preventDefault();
        modal.hidden = true;
        detach();
      };

      renderRows();
      resetEditor();
      if (kindEl) kindEl.addEventListener("change", onKindChange);
      if (rowsEl) rowsEl.addEventListener("click", onRowsClick);
      if (saveBtn) saveBtn.addEventListener("click", onSaveClick);
      if (inputEl) inputEl.addEventListener("keydown", onInputKeydown);
      if (closeBtn) closeBtn.addEventListener("click", onClose);
      detach = () => {
        try { if (kindEl) kindEl.removeEventListener("change", onKindChange); } catch {}
        try { if (rowsEl) rowsEl.removeEventListener("click", onRowsClick); } catch {}
        try { if (saveBtn) saveBtn.removeEventListener("click", onSaveClick); } catch {}
        try { if (inputEl) inputEl.removeEventListener("keydown", onInputKeydown); } catch {}
        try { if (closeBtn) closeBtn.removeEventListener("click", onClose); } catch {}
        detachModalClose();
      };
      modal.hidden = false;
      requestAnimationFrame(() => {
        if (inputEl) inputEl.focus();
      });
    };

    const openElevatorCardEditor = (mode, item) => {
      const modal = ensureVisitorElevatorCardModal();
      let detach = () => {};
      const detachModalClose = bindModalClose(modal, () => detach());
      const isEdit = mode === "edit";
      const data = item || {};
      const titleEl = modal.querySelector("#visitorElevatorCardModalTitle");
      const form = modal.querySelector("#visitorElevatorCardForm");
      const inputName = modal.querySelector("#visitorElevatorCardName");
      const inputCode = modal.querySelector("#visitorElevatorCardCode");
      const inputStatus = modal.querySelector("#visitorElevatorCardStatus");
      const statusEl = modal.querySelector("#visitorElevatorCardStatusBox");
      const closeBtn = modal.querySelector("#btnCloseVisitorElevatorCardModal");
      const submitBtn = modal.querySelector("#btnSubmitVisitorElevatorCardModal");
      const setModalStatus = (msg, isError) => {
        if (!statusEl) return;
        const t = String(msg || "").trim();
        statusEl.textContent = t;
        statusEl.hidden = !t;
        statusEl.classList.toggle("error", Boolean(isError));
      };
      if (titleEl) titleEl.textContent = isEdit ? "編輯電梯卡" : "新增電梯卡";
      if (submitBtn) submitBtn.textContent = isEdit ? "更新" : "儲存";
      renderElevatorCardNameSelect(inputName, isEdit ? String(data.name || "") : "");
      if (inputName) inputName.setAttribute("data-current-value", isEdit ? String(data.name || "") : "");
      if (inputCode) inputCode.value = isEdit ? String(data.code || "") : "";
      if (inputStatus) inputStatus.value = isEdit ? String(data.status || "available") : "available";
      setModalStatus("", false);

      const onCancel = (e) => {
        if (e) e.preventDefault();
        modal.hidden = true;
        detach();
      };
      if (closeBtn) closeBtn.addEventListener("click", onCancel);
      const onSubmit = async (e) => {
        e.preventDefault();
        if (submitBtn) submitBtn.disabled = true;
        setModalStatus("儲存中...", false);
        const name = normalizeText(inputName ? inputName.value : "");
        const code = normalizeText(inputCode ? inputCode.value : "");
        const status = normalizeText(inputStatus ? inputStatus.value : "available") || "available";
        if (!name) {
          setModalStatus("請填寫名稱。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        if (!code) {
          setModalStatus("請填寫編號。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        const docRef = isEdit ? elevatorCardCollRef().doc(String(data.id || "")) : elevatorCardCollRef().doc();
        const id = String(docRef.id || "");
        const payload = {
          name,
          code,
          status,
          sortAtMs: Date.now(),
          updatedAt: FieldValue.serverTimestamp(),
        };
        if (!isEdit) payload.createdAt = FieldValue.serverTimestamp();
        try {
          await docRef.set(payload, { merge: true });
          const sortAtMs = Number(payload.sortAtMs || Date.now()) || Date.now();
          const next = {
            id,
            name,
            code,
            status,
            sortAtMs,
            createdAt: !isEdit ? new Date() : (data.createdAt || null),
            updatedAt: new Date(),
          };
          const idx = elevatorCards.findIndex((x) => String(x.id || "") === id);
          if (idx >= 0) elevatorCards[idx] = { ...(elevatorCards[idx] || {}), ...next };
          else elevatorCards.push(next);
          modal.hidden = true;
          detach();
          renderList();
          toast(isEdit ? "已更新" : "已新增");
        } catch (err) {
          const codeText = String(err && err.code ? err.code : "");
          setModalStatus(codeText.includes("permission-denied") ? "沒有權限執行此操作。" : "儲存失敗，請稍後再試。", true);
        } finally {
          if (submitBtn) submitBtn.disabled = false;
        }
      };
      form.addEventListener("submit", onSubmit);
      detach = () => {
        try { form.removeEventListener("submit", onSubmit); } catch {}
        try { if (closeBtn) closeBtn.removeEventListener("click", onCancel); } catch {}
        detachModalClose();
      };
      modal.hidden = false;
      requestAnimationFrame(() => {
        if (inputName) inputName.focus();
      });
    };

    const openVisitorEditor = async (mode, item) => {
      residentOptions = await loadResidentOptions();
      const modal = ensureVisitorModal();
      let detach = () => {};
      const detachModalClose = bindModalClose(modal, () => detach());

      const titleEl = modal.querySelector("#visitorModalTitle");
      const form = modal.querySelector("#visitorModalForm");
      const st = modal.querySelector("#visitorModalStatus");
      const inputName = modal.querySelector("#modal_v_name");
      const inputEmail = modal.querySelector("#modal_v_email");
      const inputPhone = modal.querySelector("#modal_v_phone");
      const inputUnit = modal.querySelector("#modal_v_unit");
      const unitDatalist = modal.querySelector("#visitorUnitOptions");
      const unitPicker = modal.querySelector("#visitorUnitPicker");
      const pickUnitBtn = modal.querySelector("#btnPickVisitorUnit");
      const inputPartySize = modal.querySelector("#modal_v_partySize");
      const inputPlate = modal.querySelector("#modal_v_plate");
      const purposeTypeEl = modal.querySelector("#modal_v_purposeType");
      const purposeOtherField = modal.querySelector("#modal_v_purposeOtherField");
      const purposeOtherEl = modal.querySelector("#modal_v_purposeOther");
      const inputNote = modal.querySelector("#modal_v_note");
      const timesRow = modal.querySelector("#modal_v_times_row");
      const inputInAt = modal.querySelector("#modal_v_inAt");
      const inputOutAt = modal.querySelector("#modal_v_outAt");
      const keepCertEl = modal.querySelector("#modal_v_keep_cert");
      const keepCertTypeEl = modal.querySelector("#modal_v_keep_cert_type");
      const keepCardEl = modal.querySelector("#modal_v_keep_card");
      const keepCashEl = modal.querySelector("#modal_v_keep_cash");
      const keepCashAmountEl = modal.querySelector("#modal_v_keep_cash_amount");
      const keepKeyEl = modal.querySelector("#modal_v_keep_key");
      const cancelBtn = modal.querySelector("#btnCancelVisitorModal");
      const closeBtn = modal.querySelector("#btnCloseVisitorModal");
      const submitBtn = modal.querySelector("#btnSubmitVisitorModal");

      const setModalStatus = (msg, isError) => {
        if (!st) return;
        const t = String(msg || "").trim();
        st.textContent = t;
        st.hidden = !t;
        st.classList.toggle("error", Boolean(isError));
      };

      const isEdit = mode === "edit";
      const data = item || {};
      if (titleEl) titleEl.textContent = isEdit ? "編輯訪客" : "新增訪客";
      if (submitBtn) submitBtn.textContent = isEdit ? "更新" : "建立";
      if (inputName) inputName.value = isEdit ? String(data.name || "") : "";
      if (inputEmail) inputEmail.value = isEdit ? String(data.email || "") : "";
      if (inputPhone) inputPhone.value = isEdit ? String(data.phone || "") : "";
      if (inputUnit) inputUnit.value = isEdit ? String(data.unit || "") : "";
      if (inputPartySize) inputPartySize.value = String(isEdit && data.partySize != null ? Number(data.partySize) : 1);
      if (inputPlate) inputPlate.value = isEdit ? String(data.plate || "") : "";
      if (inputNote) inputNote.value = isEdit ? String(data.note || "") : "";
      if (timesRow) timesRow.hidden = !isEdit;
      if (inputInAt) inputInAt.value = isEdit ? toLocalInputValue(toDate(data.inAt)) : "";
      if (inputOutAt) inputOutAt.value = isEdit ? toLocalInputValue(toDate(data.outAt)) : "";

      const normalizePurposeType = (raw) => {
        const v = String(raw || "").trim();
        const known = ["親友拜訪", "施工修繕", "快遞外送", "其他"];
        if (known.includes(v)) return v;
        if (!v) return "親友拜訪";
        return "其他";
      };
      const existingPurpose = String(data.purpose || "");
      const existingPurposeType = normalizePurposeType(String(data.purposeType || existingPurpose));
      const existingOther = existingPurposeType === "其他" ? String(data.purposeOther || (existingPurposeType === existingPurpose ? "" : existingPurpose) || "") : "";
      if (purposeTypeEl) purposeTypeEl.value = existingPurposeType;
      if (purposeOtherEl) purposeOtherEl.value = existingOther;

      const setPurposeOtherVisible = () => {
        const isOther = purposeTypeEl && String(purposeTypeEl.value || "") === "其他";
        if (purposeOtherField) {
          purposeOtherField.hidden = !isOther;
          purposeOtherField.style.display = isOther ? "" : "none";
        }
      };
      setPurposeOtherVisible();
      setModalStatus("", false);

      if (unitDatalist) {
        unitDatalist.innerHTML = residentOptions.map((u) => {
          const uid = String(u.id || "");
          const name = String(u.name || "");
          return `<option value="${uid.replace(/"/g, "&quot;")}" label="${name.replace(/"/g, "&quot;")}"></option>`;
        }).join("");
      }

      const closeUnitPicker = () => {
        if (unitPicker) unitPicker.hidden = true;
        if (pickUnitBtn) pickUnitBtn.classList.remove("active");
      };

      const renderUnitPicker = () => {
        if (!unitPicker) return;
        unitPicker.innerHTML = "";
        let count = 0;
        (Array.isArray(residentOptions) ? residentOptions : []).forEach((u) => {
          const uid = String(u.id || "").trim();
          if (!uid) return;
          const name = String(u.name || "").trim();
          const btn = document.createElement("button");
          btn.type = "button";
          btn.className = "unit-option";
          const idSpan = document.createElement("span");
          idSpan.className = "unit-id";
          idSpan.textContent = uid;
          btn.appendChild(idSpan);
          if (name) {
            const nameSpan = document.createElement("span");
            nameSpan.className = "unit-name";
            nameSpan.textContent = name;
            btn.appendChild(nameSpan);
          }
          btn.addEventListener("click", () => {
            if (inputUnit) {
              inputUnit.value = uid;
              inputUnit.dispatchEvent(new Event("input", { bubbles: true }));
              inputUnit.focus();
            }
            closeUnitPicker();
          });
          unitPicker.appendChild(btn);
          count += 1;
        });
        if (!count) {
          const empty = document.createElement("div");
          empty.className = "unit-empty";
          empty.textContent = "尚無戶號資料";
          unitPicker.appendChild(empty);
        }
      };

      const onToggleUnitPicker = (e) => {
        e.preventDefault();
        if (!unitPicker) return;
        if (unitPicker.hidden) {
          renderUnitPicker();
          unitPicker.hidden = false;
          if (pickUnitBtn) pickUnitBtn.classList.add("active");
        } else {
          closeUnitPicker();
        }
      };
      if (pickUnitBtn) pickUnitBtn.addEventListener("click", onToggleUnitPicker);

      const onDocClickUnitPicker = (e) => {
        if (!unitPicker || unitPicker.hidden) return;
        const t = e.target;
        if (unitPicker.contains(t)) return;
        if (pickUnitBtn && pickUnitBtn.contains(t)) return;
        closeUnitPicker();
      };
      document.addEventListener("click", onDocClickUnitPicker);
      closeUnitPicker();

      detach = () => {
        detachModalClose();
        document.removeEventListener("click", onDocClickUnitPicker);
        closeUnitPicker();
      };

      const applyKeepState = () => {
        const keepCert = Boolean(keepCertEl && keepCertEl.checked);
        const keepCash = Boolean(keepCashEl && keepCashEl.checked);
        if (keepCertTypeEl) keepCertTypeEl.disabled = !keepCert;
        if (keepCashAmountEl) keepCashAmountEl.disabled = !keepCash;
        if (!keepCert && keepCertTypeEl) keepCertTypeEl.value = getDefaultVisitorKeepCertType();
        if (!keepCash && keepCashAmountEl) keepCashAmountEl.value = "";
      };

      const loadKeepFromData = () => {
        const keep = (data && data.keep) || {};
        const cert = keep && keep.certificate ? keep.certificate : {};
        const cash = keep && keep.cash ? keep.cash : {};
        if (keepCertEl) keepCertEl.checked = Boolean(cert && cert.enabled);
        if (keepCertTypeEl) {
          const keepCertType = String((cert && cert.type) || getDefaultVisitorKeepCertType());
          renderVisitorKeepCertTypeSelect(keepCertTypeEl, keepCertType);
          keepCertTypeEl.setAttribute("data-current-value", keepCertType);
        }
        if (keepCardEl) keepCardEl.checked = Boolean(keep && keep.businessCard);
        if (keepCashEl) keepCashEl.checked = Boolean(cash && cash.enabled);
        if (keepCashAmountEl) keepCashAmountEl.value = cash && cash.amount != null ? String(cash.amount) : "";
        if (keepKeyEl) keepKeyEl.checked = Boolean(keep && keep.key);
        applyKeepState();
      };
      loadKeepFromData();

      const onCancel = (e) => {
        e.preventDefault();
        modal.hidden = true;
        detach();
      };
      if (cancelBtn) cancelBtn.addEventListener("click", onCancel);
      if (closeBtn) closeBtn.addEventListener("click", onCancel);
      if (purposeTypeEl) purposeTypeEl.addEventListener("change", setPurposeOtherVisible);
      if (keepCertEl) keepCertEl.addEventListener("change", applyKeepState);
      if (keepCashEl) keepCashEl.addEventListener("change", applyKeepState);

      const onSubmit = async (e) => {
        e.preventDefault();
        if (submitBtn) submitBtn.disabled = true;
        setModalStatus("儲存中...", false);

        const name = normalizeText(inputName ? inputName.value : "");
        const email = normalizeText(inputEmail ? inputEmail.value : "");
        const phone = normalizeText(inputPhone ? inputPhone.value : "");
        const unit = normalizeText(inputUnit ? inputUnit.value : "");
        const partySizeRaw = inputPartySize ? Number(inputPartySize.value) : 1;
        const partySize = Number.isFinite(partySizeRaw) && partySizeRaw >= 1 ? Math.floor(partySizeRaw) : 1;
        const plate = normalizeText(inputPlate ? inputPlate.value : "");
        const purposeType = normalizeText(purposeTypeEl ? purposeTypeEl.value : "");
        const purposeOther = normalizeText(purposeOtherEl ? purposeOtherEl.value : "");
        const purpose = purposeType === "其他" ? purposeOther : purposeType;
        const note = normalizeText(inputNote ? inputNote.value : "");
        const inDate = isEdit ? (parseLocalInputValue(inputInAt ? inputInAt.value : "") || toDate(data.inAt) || null) : null;
        const outDate = isEdit ? (parseLocalInputValue(inputOutAt ? inputOutAt.value : "") || null) : null;

        if (!name) {
          setModalStatus("請填寫訪客姓名。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }
        if (purposeType === "其他" && !purposeOther) {
          setModalStatus("請填寫到訪事由。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }

        const keep = {
          certificate: {
            enabled: Boolean(keepCertEl && keepCertEl.checked),
            type: String(keepCertTypeEl ? keepCertTypeEl.value : getDefaultVisitorKeepCertType()),
          },
          businessCard: Boolean(keepCardEl && keepCardEl.checked),
          cash: {
            enabled: Boolean(keepCashEl && keepCashEl.checked),
            amount: keepCashEl && keepCashEl.checked ? Number(keepCashAmountEl ? keepCashAmountEl.value : "") : null,
          },
          key: Boolean(keepKeyEl && keepKeyEl.checked),
          elevatorCard: data && data.keep && data.keep.elevatorCard ? data.keep.elevatorCard : { enabled: false },
        };
        if (!Number.isFinite(keep.cash.amount)) keep.cash.amount = null;

        const Timestamp = firebase.firestore.Timestamp;
        const docRef = isEdit ? collRef().doc(String(data.id || "")) : collRef().doc();
        const id = String(docRef.id || "");
      const creatorLabel = !isEdit ? (await getCreatorLabel80(String((auth.currentUser && auth.currentUser.uid) || "")).catch(() => "") || creatorName) : "";
        const payload = {
          qrToken: id,
          name,
          email,
          phone,
          unit,
          partySize,
          plate,
          purpose,
          purposeType: purposeType === "其他" ? "其他" : purposeType,
          purposeOther: purposeType === "其他" ? purposeOther : "",
          note,
          inAt: isEdit && inDate ? Timestamp.fromDate(inDate) : null,
          outAt: isEdit && outDate ? Timestamp.fromDate(outDate) : null,
          keep,
          updatedAt: FieldValue.serverTimestamp(),
        };
        if (!isEdit) {
          payload.createdAt = FieldValue.serverTimestamp();
          payload.createdBy = String((auth.currentUser && auth.currentUser.uid) || "");
        payload.createdByName = String(creatorLabel || "").trim();
          payload.qrIssuedAt = FieldValue.serverTimestamp();
          payload.status = "pending";
          payload.passAuthorized = false;
        }
        try {
          await docRef.set(payload, { merge: true });
        } catch (err) {
          const code = String(err && err.code ? err.code : "");
          setModalStatus(code.includes("permission-denied") ? "沒有權限執行此操作。" : "儲存失敗，請稍後再試。", true);
          if (submitBtn) submitBtn.disabled = false;
          return;
        }

        modal.hidden = true;
        detach();

        const clientCreatedAt = Timestamp.fromDate(new Date());
        try {
          const nextItem = {
            id,
            qrToken: id,
            name,
            email,
            phone,
            unit,
            plate,
            purpose,
            purposeType: payload.purposeType,
            purposeOther: payload.purposeOther,
            note,
            inAt: payload.inAt,
            outAt: payload.outAt,
            partySize,
            keep,
            createdBy: !isEdit ? String((auth.currentUser && auth.currentUser.uid) || "") : String(data.createdBy || ""),
            createdByName: !isEdit ? String(creatorLabel || "").trim() : String(data.createdByName || ""),
            createdAt: !isEdit ? clientCreatedAt : (data.createdAt || null),
            status: !isEdit ? "pending" : (data.status || "pending"),
            passAuthorized: !isEdit ? false : (data.passAuthorized || false),
          };
          const idx = visitors.findIndex((x) => String(x.id || "") === id);
          if (idx >= 0) visitors[idx] = { ...(visitors[idx] || {}), ...nextItem };
          else visitors.unshift(nextItem);

          visitors.sort((a, b) => {
            const at = (toDate(a.inAt) || toDate(a.createdAt) || new Date(0)).getTime();
            const bt = (toDate(b.inAt) || toDate(b.createdAt) || new Date(0)).getTime();
            return bt - at;
          });
          renderList();
          if (!isEdit) toast("登記完成");
        } catch {
          toast("已儲存，但畫面更新失敗");
        }

        if (submitBtn) submitBtn.disabled = false;
      };

      form.addEventListener("submit", onSubmit);
      const oldDetach = detach;
      detach = () => {
        try { form.removeEventListener("submit", onSubmit); } catch {}
        try {
          if (cancelBtn) cancelBtn.removeEventListener("click", onCancel);
          if (closeBtn) closeBtn.removeEventListener("click", onCancel);
        } catch {}
        try {
          if (purposeTypeEl) purposeTypeEl.removeEventListener("change", setPurposeOtherVisible);
          if (keepCertEl) keepCertEl.removeEventListener("change", applyKeepState);
          if (keepCashEl) keepCashEl.removeEventListener("change", applyKeepState);
        } catch {}
        oldDetach();
      };

      modal.hidden = false;
      requestAnimationFrame(() => {
        if (inputName) inputName.focus();
      });
    };

    if (searchEl) searchEl.addEventListener("input", renderList);
    if (dateEl) dateEl.addEventListener("change", renderList);

    if (historyUnitEl) {
      historyUnitEl.addEventListener("change", () => {
        historyUnit = String(historyUnitEl.value || "");
        renderList();
      });
    }
    if (historyBrowseBtn) {
      historyBrowseBtn.addEventListener("click", async () => {
        if (!historyUnit) {
          toast("請先選擇戶號。");
          return;
        }
        historyBrowseBtn.disabled = true;
        try {
          await publishUnitHistory(historyUnit);
        } catch (err) {
          const code = String(err && err.code ? err.code : "");
          toast(code.includes("permission-denied") ? "公開資料發佈失敗：沒有權限。" : "公開資料發佈失敗，請稍後再試。");
        } finally {
          historyBrowseBtn.disabled = false;
        }
        const url = `visitor-history.html?c=${encodeURIComponent(String(visitorCommunitySlug || ""))}&u=${encodeURIComponent(historyUnit)}&m=${encodeURIComponent(currentMonthKey())}`;
        window.open(url, "_blank");
      });
    }
    if (historyExcelBtn) historyExcelBtn.addEventListener("click", exportHistoryExcel);

    if (addBtn) addBtn.addEventListener("click", () => openVisitorEditor("create"));
    if (addElevatorCardBtn) addElevatorCardBtn.addEventListener("click", () => openElevatorCardEditor("create"));
    if (openElevatorCardNameSettingsBtn) openElevatorCardNameSettingsBtn.addEventListener("click", openElevatorCardNameSettings);
    if (scanBtn) scanBtn.addEventListener("click", () => openVisitorScanModal80({ cid: visitorCommunitySlug, onApplied: applyLocalVisitorPatch }));
    if (visitorQrBtn) visitorQrBtn.addEventListener("click", () => openVisitorQrModal80({ communityId: cid, communityName: cname }));

    if (listEl) {
      listEl.addEventListener("click", async (e) => {
        const editBtn = e.target && e.target.closest ? e.target.closest("[data-card-edit]") : null;
        if (editBtn) {
          const id = String(editBtn.getAttribute("data-card-edit") || "").trim();
          const item = elevatorCards.find((x) => String(x.id || "") === id) || null;
          if (item) openElevatorCardEditor("edit", item);
          return;
        }
        const delBtn = e.target && e.target.closest ? e.target.closest("[data-card-delete]") : null;
        if (!delBtn) return;
        const id = String(delBtn.getAttribute("data-card-delete") || "").trim();
        const item = elevatorCards.find((x) => String(x.id || "") === id) || null;
        if (!item) return;
        const ok = await (window.nwConfirm ? window.nwConfirm({
          title: "確認刪除",
          message: `確定要刪除電梯卡「${String(item.name || id)}」？`,
          okText: "刪除",
          cancelText: "取消",
          danger: true,
        }) : Promise.resolve(window.confirm("確定要刪除？")));
        if (!ok) return;
        delBtn.disabled = true;
        try {
          await elevatorCardCollRef().doc(id).delete();
          elevatorCards = elevatorCards.filter((x) => String(x.id || "") !== id);
          renderList();
          toast("已刪除");
        } catch (err) {
          const codeText = String(err && err.code ? err.code : "");
          toast(codeText.includes("permission-denied") ? "沒有權限刪除。" : "刪除失敗");
        } finally {
          delBtn.disabled = false;
        }
      });
    }

    if (listEl && !listEl._timePillBound) {
      listEl._timePillBound = true;
      listEl.addEventListener("click", (e) => {
        const pill = e.target && e.target.closest ? e.target.closest(".time-pill[data-time-kind]") : null;
        if (!pill || !listEl.contains(pill)) return;
        e.preventDefault();
        openTimeEditorFromPill(pill);
      });
      listEl.addEventListener("keydown", (e) => {
        if (e.key !== "Enter" && e.key !== " ") return;
        const pill = e.target && e.target.closest ? e.target.closest(".time-pill[data-time-kind]") : null;
        if (!pill || !listEl.contains(pill)) return;
        e.preventDefault();
        openTimeEditorFromPill(pill);
      });
    }

    if (listEl) {
      listEl.addEventListener("click", async (e) => {
        const row = e.target && e.target.closest ? e.target.closest(".visitor-item") : null;
        if (!row) return;
        const id = row.getAttribute("data-id");
        const v = visitors.find((x) => String(x.id || "") === String(id || "")) || null;
        if (!id || !v) return;

        const editBtn = e.target.closest("[data-edit]");
        if (editBtn) {
          openVisitorEditor("edit", v);
          return;
        }

        const passBtn = e.target.closest("[data-pass]");
        if (passBtn) {
          const isPending = String(v.status || "").toLowerCase() === "pending";
          if (isPending) {
            const ok = await (window.nwConfirm ? window.nwConfirm({
              title: "訪客核准",
              message: `是否同意訪客「${String(v.name || "")}」的登記並核發訪客證？`,
              okText: "同意",
              cancelText: "不同意",
              danger: false,
            }) : Promise.resolve(window.confirm("是否同意核准？")));
            
            if (ok) {
              try {
                await collRef().doc(String(id)).update({
                  status: "approved",
                  passAuthorized: true,
                  updatedAt: FieldValue.serverTimestamp(),
                });
                v.status = "approved";
                v.passAuthorized = true;
                renderList();
                openVisitorPassModal80({
                  cid: visitorCommunitySlug,
                  communityName: cname,
                  visitorId: id,
                  qrToken: String(v.qrToken || "").trim(),
                  name: String(v.name || ""),
                  unit: String(v.unit || ""),
                  purpose: String(v.purpose || ""),
                  phone: String(v.phone || ""),
                  plate: String(v.plate || ""),
                  email: String(v.email || ""),
                  partySize: v.partySize != null ? Number(v.partySize) : 1,
                  keep: v.keep || null,
                  createdAt: v.createdAt || null,
                  createdByName: String(v.createdByName || "").trim(),
                  inAt: v.inAt || null,
                  outAt: v.outAt || null,
                });
              } catch (err) {
                toast("核准失敗");
              }
            }
            return;
          }

          let createdByLabel = String(v.createdByName || "").trim();
          if (v.createdBy) {
            const resolved = await getCreatorLabel80(String(v.createdBy || "")).catch(() => "");
            if (String(resolved || "").trim()) createdByLabel = String(resolved || "").trim();
          }
          openVisitorPassModal80({
            cid: visitorCommunitySlug,
            communityName: cname,
            visitorId: id,
            qrToken: String(v.qrToken || "").trim(),
            name: String(v.name || ""),
            unit: String(v.unit || ""),
            purpose: String(v.purpose || ""),
            phone: String(v.phone || ""),
            plate: String(v.plate || ""),
            email: String(v.email || ""),
            partySize: v.partySize != null ? Number(v.partySize) : 1,
            keep: v.keep || null,
            createdAt: v.createdAt || null,
            createdByName: createdByLabel,
            inAt: v.inAt || null,
            outAt: v.outAt || null,
          });
          return;
        }
        const delBtn = e.target.closest("[data-delete]");
        if (delBtn) {
          const ok = await (window.nwConfirm ? window.nwConfirm({
            title: "確認刪除",
            message: `確定要刪除訪客「${String(v.name || id)}」的登記？`,
            okText: "刪除",
            cancelText: "取消",
            danger: true,
          }) : Promise.resolve(window.confirm("確定要刪除？")));
          if (!ok) return;
          delBtn.disabled = true;
          try {
            await collRef().doc(String(id)).delete();
            visitors = visitors.filter((x) => String(x.id || "") !== String(id));
            renderList();
          } catch {
            toast("刪除失敗");
          } finally {
            delBtn.disabled = false;
          }
        }
      });
    }

    subscribeVisitors();
    updateFooterActiveNav();
  }

  function setupDashboardReorder(grid) {
    if (!grid || grid._reorderBound) return;
    grid._reorderBound = true;

    let pressTimer = 0;
    let dragging = false;
    let draggingEl = null;
    let pressedEl = null;
    let placeholderEl = null;
    let ghostEl = null;
    let didDrag = false;
    let lastPointerId = null;
    let offsetX = 0;
    let offsetY = 0;
    let startX = 0;
    let startY = 0;
    let detachDocListeners = () => {};

    const clearPressTimer = () => {
      if (pressTimer) window.clearTimeout(pressTimer);
      pressTimer = 0;
    };

    const stopDragging = () => {
      clearPressTimer();
      detachDocListeners();
      detachDocListeners = () => {};
      if (!dragging) return;
      dragging = false;
      if (ghostEl && ghostEl.parentNode) ghostEl.parentNode.removeChild(ghostEl);
      ghostEl = null;
      if (placeholderEl && placeholderEl.parentNode && draggingEl) {
        try {
          placeholderEl.parentNode.insertBefore(draggingEl, placeholderEl);
        } catch {}
        placeholderEl.parentNode.removeChild(placeholderEl);
      }
      placeholderEl = null;
      if (draggingEl) draggingEl.style.display = "";
      if (draggingEl) draggingEl.classList.remove("dragging");
      if (draggingEl) draggingEl.classList.remove("pressing");
      draggingEl = null;
      if (pressedEl) pressedEl.classList.remove("pressing");
      pressedEl = null;
      grid.classList.remove("reorder-mode");
      const cid = resolveActiveCommunityId();
      const ids = Array.from(grid.querySelectorAll(".card[data-id]"))
        .map((el) => String(el.getAttribute("data-id") || "").trim())
        .filter(Boolean);
      saveModuleOrder(cid, ids);
      renderFooterNav();
      updateFooterActiveNav();
    };

    const updateGhostPosition = (e) => {
      if (!ghostEl) return;
      const x = Math.round(e.clientX - offsetX);
      const y = Math.round(e.clientY - offsetY);
      ghostEl.style.left = `${x}px`;
      ghostEl.style.top = `${y}px`;
    };

    const movePlaceholder = (clientX, clientY) => {
      if (!placeholderEl) return;
      const el = document.elementFromPoint(clientX, clientY);
      const over = el && el.closest ? el.closest(".card[data-id]") : null;
      if (!over || !grid.contains(over)) return;
      if (over === placeholderEl) return;
      if (draggingEl && over === draggingEl) return;
      const rect = over.getBoundingClientRect();
      const before = clientY < rect.top + rect.height / 2;
      if (before) {
        if (over.previousElementSibling !== placeholderEl) grid.insertBefore(placeholderEl, over);
      } else {
        if (over.nextElementSibling !== placeholderEl) grid.insertBefore(placeholderEl, over.nextElementSibling);
      }
    };

    grid.addEventListener("pointerdown", (e) => {
      const card = e.target && e.target.closest ? e.target.closest(".card[data-id]") : null;
      if (!card || !grid.contains(card)) return;
      if (e.target && e.target.closest && e.target.closest("button,a,input,textarea,select,label")) return;
      didDrag = false;
      lastPointerId = e.pointerId;
      startX = e.clientX;
      startY = e.clientY;
      if (pressedEl && pressedEl !== card) pressedEl.classList.remove("pressing");
      pressedEl = card;
      card.classList.add("pressing");
      clearPressTimer();
      pressTimer = window.setTimeout(() => {
        dragging = true;
        didDrag = true;
        draggingEl = card;
        grid.classList.add("reorder-mode");
        card.classList.add("dragging");
        card.classList.remove("pressing");

        const rect = card.getBoundingClientRect();
        offsetX = startX - rect.left;
        offsetY = startY - rect.top;

        placeholderEl = document.createElement("div");
        placeholderEl.className = "card placeholder";
        placeholderEl.style.height = `${Math.round(rect.height)}px`;
        placeholderEl.style.width = `${Math.round(rect.width)}px`;
        grid.insertBefore(placeholderEl, card);

        ghostEl = card.cloneNode(true);
        ghostEl.classList.add("drag-ghost");
        ghostEl.style.display = "";
        ghostEl.style.width = `${Math.round(rect.width)}px`;
        ghostEl.style.height = `${Math.round(rect.height)}px`;
        ghostEl.style.left = `${Math.round(rect.left)}px`;
        ghostEl.style.top = `${Math.round(rect.top)}px`;
        document.body.appendChild(ghostEl);
        card.style.display = "none";

        const onMove = (ev) => {
          if (!dragging) return;
          updateGhostPosition(ev);
          movePlaceholder(ev.clientX, ev.clientY);
          ev.preventDefault();
        };
        const onUp = () => stopDragging();
        document.addEventListener("pointermove", onMove, { passive: false });
        document.addEventListener("pointerup", onUp);
        document.addEventListener("pointercancel", onUp);
        detachDocListeners = () => {
          document.removeEventListener("pointermove", onMove);
          document.removeEventListener("pointerup", onUp);
          document.removeEventListener("pointercancel", onUp);
        };

        updateGhostPosition({ clientX: startX, clientY: startY });
        movePlaceholder(startX, startY);
      }, 380);
    });

    grid.addEventListener("pointerup", () => {
      clearPressTimer();
      if (pressedEl) pressedEl.classList.remove("pressing");
      pressedEl = null;
    });
    grid.addEventListener("pointercancel", () => {
      clearPressTimer();
      if (pressedEl) pressedEl.classList.remove("pressing");
      pressedEl = null;
      stopDragging();
    });

    grid.addEventListener("click", (e) => {
      if (!didDrag) return;
      e.preventDefault();
      e.stopPropagation();
      didDrag = false;
    }, true);
  }

  /* 總覽卡片說明文字：全部以跑馬燈顯示，依距離換算等速捲動秒數 */
  let moduleDescResizeHandler = null;

  function applyModuleDescMarquee() {
    const grid = document.getElementById("moduleGrid");
    if (!grid) return;
    grid.querySelectorAll("p.module-desc > span").forEach((span) => {
      const dist = span.scrollWidth;
      if (!dist) return;
      span.style.setProperty("--marquee-dur", Math.max(8, Math.round(dist / 45)) + "s");
    });
  }

  function manualViewerHref(id, name) {
    const file = `manual/${encodeURIComponent(String(id || "").trim())}.pdf`;
    const filename = `${String(name || "").trim() || "手冊"}操作手冊.pdf`;
    return `pdf-viewer.html?file=${file}&name=${encodeURIComponent(filename)}`;
  }

  function renderDashboard() {
    clearPageHeader();
    stopDashboardClock();
    const layoutEl = document.querySelector(".layout");
    if (layoutEl) layoutEl.classList.remove("visitor-main-lock");
    if (subnavEl) subnavEl.innerHTML = "";
    stopVisitorsSubscription();
    contentEl.innerHTML = `
      <div class="grid" id="moduleGrid"></div>
    `;
    renderDashboardMidtop();
    const grid = document.getElementById("moduleGrid");
    grid.innerHTML = orderedModules().map((m) => {
      const cfg = resolveUrl(m.id);
      const disabled = !cfg.enabled || !cfg.url;
      return `
        <article class="card" data-id="${m.id}" role="button" tabindex="0" aria-label="${m.name}" ${disabled ? "aria-disabled=\"true\"" : ""}>
          <div class="card-hd">
            <div class="left">
              <div class="chip" aria-hidden="true">${iconSvg(m.id)}</div>
              <div class="module-copy">
                <h2>${m.name}</h2>
              </div>
            </div>
            <p class="module-desc"><span>${m.desc}</span></p>
            <a class="tag red manual-btn" data-manual="${m.id}" href="${manualViewerHref(m.id, m.name)}" target="_blank" rel="noopener" title="開啟 ${m.name} 操作手冊" aria-label="開啟 ${m.name} 操作手冊"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 6.6C10.6 5.3 8.6 4.6 6.2 4.6H4v13.2h2.2c2.4 0 4.4.7 5.8 2 1.4-1.3 3.4-2 5.8-2H20V4.6h-2.2c-2.4 0-4.4.7-5.8 2Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/><path d="M12 6.6v12.2" stroke="currentColor" stroke-width="1.7"/></svg></a>
          </div>
          <div class="card-bd">
            <button class="btn ${disabled ? "" : "btn-primary"}" type="button" data-open ${disabled ? "disabled" : ""}>進入</button>
          </div>
        </article>
      `;
    }).join("");

    const openModule = (id) => {
      const { url } = resolveUrl(id);
      if (!url) {
        toast("尚未設定連結（示意）");
        return;
      }
      location.href = url;
    };

    grid.querySelectorAll("article.card").forEach((card) => {
      const id = card.getAttribute("data-id");
      const disabled = card.getAttribute("aria-disabled") === "true";
      card.addEventListener("click", (e) => {
        if (didDrag) { didDrag = false; return; }
        if (e.target.closest("[data-manual]")) return;
        if (disabled) return;
        if (e.target.closest("[data-open]")) return;
        openModule(id);
      });
      card.addEventListener("keydown", (e) => {
        if (e.target.closest("[data-manual]")) return;
        if (disabled) return;
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          openModule(id);
        }
      });
    });

    grid.querySelectorAll("[data-open]").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const card = btn.closest("[data-id]");
        const id = card.getAttribute("data-id");
        openModule(id);
      });
    });
    updateFooterActiveNav();
    setupDashboardReorder(grid);
    applyModuleDescMarquee();
    if (moduleDescResizeHandler) window.removeEventListener("resize", moduleDescResizeHandler);
    let marqueeResizeTimer = 0;
    moduleDescResizeHandler = () => {
      window.clearTimeout(marqueeResizeTimer);
      marqueeResizeTimer = window.setTimeout(applyModuleDescMarquee, 150);
    };
    window.addEventListener("resize", moduleDescResizeHandler);
  }

